/* Evolvlings: path conversations of era 6, La Corte de los Nombres (the ten eras plan, https://claude.ai/artifact/RFy6uGdhz9DJeW7e9ZfdkE).
   Same format as the zone files (see rpg/events-aurora.js). These events only come up while the Glade lives in era 6:
   need.era says so (lore.js needOk), and need.layer counts the guardians beaten since the era began.
   Another generation has passed since El Invierno Largo. How era 5 ended (m5_tumba / m5_boda / m5_deshielo) and who
   carried the blame in era 3 (m3_culpaCasas / m3_culpaCorte / m3_culpaNadie) are still in the flags and change a few
   lines and options.
   After the winter everyone has something to forget, and the Veiled Court sells it: under the Hollow there is root
   shadow, and whoever breathes it forgets what they choose. With it, the pact is forgotten too.
   The nine peoples you bring together set the u6_* flags; with all nine, the final dilemma offers A Kept Name
   (rpg/data-eras.js derives e6_nueve). The m6_* flags are the marks this era leaves on the next.
   Loaded after the zone files (it adds to them). English text: rpg/events-era6.en.js. */
window.EVEVENTS = window.EVEVENTS || {};
(function (E) {
  const add = (zone, evs) => { E[zone] = Object.assign(E[zone] || {}, evs); };

  /* ==================== Entrega 1: los pozos de sombra, la reina, la Nombrada, el culpable que olvidó y el final ==================== */

  /* ---------- Hondonada Umbría: los pozos, el vendedor de olvido, la reina, la Nombrada y el archivero ---------- */
  add("hollow", {
    "e6-pozos": { kind: "encuentro", need: { era: 6, layer: 1 }, first: true, who: { desmemoria: "Desmemoria, del pozo" }, start: "a", nodes: {
      a: { say: [[null, "En el fondo de la Hondonada hay una cola larga que baja por la ladera y se mete en la oscuridad. Al final, en una cueva, hay tres pozos redondos. No tienen agua: tienen sombra, quieta, espesa, que respira."],
                 ["desmemoria", "Soy Desmemoria. Atiendo el pozo del medio. Usted se asoma, respira hondo, y piensa en lo que quiere dejar de recordar. Cuando sube, ya no está. Una moneda por recuerdo."],
                 ["desmemoria", "Hoy vinieron ciento doce. Una viuda, un ladrón, un chico que le pegó a su hermano. Todos vienen por lo mismo: el invierno. Lo que hicieron, lo que no hicieron."]],
           opts: [{ t: "«¿Adónde va lo que se olvida?»", go: "adonde", once: true },
                  { t: "«¿La Corte se queda con algo?»", go: "corte", once: true },
                  { t: "Ayudar a Desmemoria a atender la cola", go: "atender" },
                  { t: "Asomarte a un pozo, sin respirar", go: "mirar" },
                  { t: "Irte", go: "irte" }] },
      adonde: { say: [["desmemoria", "Abajo. No sé adónde. La sombra se lo lleva y no lo devuelve. Nunca vi que nadie recuperara nada."],
                      ["desmemoria", "Mi abuela decía que la sombra es de la Raíz. Que la Raíz se traga lo que olvidamos. No sé si es verdad. Es lo que se dice en la Corte cuando se quiere asustar a los chicos."]], back: "a" },
      corte: { say: [["desmemoria", "La moneda. Y una lista: quién vino. No qué olvidó: eso no lo sabe nadie, ni yo. Solo el nombre."],
                     ["desmemoria", "Yo olvido la lista cada noche. Me lo pidió la reina. Así nadie me puede obligar a decirla."]], back: "a" },
      atender: { say: [[null, "Pasas la tarde en la cueva. Le das la mano a una vieja para que no se caiga en el pozo. Le alcanzas un pañuelo a un hombre que llora antes de asomarse."],
                       [null, "Un chico llega con una moneda y no sabe qué quiere olvidar. Desmemoria le devuelve la moneda y lo manda de vuelta."],
                       ["desmemoria", "Si no sabe qué olvidar, no hay que olvidar nada. Esa es mi regla. La Corte no la tiene. Gracias por la tarde. Ya no me acuerdo de la última vez que alguien me ayudó, y no es por el pozo."]], end: { xp: 14, flag: "e6_colaAtendida" } },
      mirar: { say: [[null, "Te asomas al pozo del medio sin respirar. La sombra se mueve. Adentro, muy lejos, pasan cosas: una cara, una puerta, una mano dando pan. Recuerdos de otros."],
                     [null, "Uno se detiene y te mira. Es una nana. Alguien la olvidó aquí. La reconoces: es la de la Estrella."],
                     ["desmemoria", "Salga. Salga. Si respira ahí adentro, no sabe qué se le va. Hay gente que vino a olvidar una deuda y se olvidó de su hija."]], end: { xp: 16, flag: "e6_pozoVisto" } },
      irte: { say: [[null, "Subes por la ladera, contra la cola. Nadie te mira. Todos miran el suelo, ensayando en voz baja lo que van a olvidar."]], end: { xp: 6 } },
    } },

    "e6-olvidar": { kind: "dialogo", need: { era: 6, layer: 2 }, who: { desmemoria: "Desmemoria, del pozo" }, start: "a", nodes: {
      a: { say: [[null, "Es tarde. La cola se terminó. Desmemoria está sentado al borde del pozo del medio, con los pies colgando sobre la sombra."],
                 ["desmemoria", "Usted lleva un libro. Lo he visto. Recuerda cosas de antes, de mucho antes. Cosas que la gente pagó por olvidar."],
                 ["desmemoria", "No le cobro. Si quiere, puede dejar algo aquí. Algo de antes, que le pese. Lo que pase en el pozo, se queda en el pozo. Su libro va a tener una página en gris."]],
           opts: [{ t: "«¿Usted qué olvidó?»", go: "usted", once: true },
                  { t: "Asomarte y olvidar algo de una era pasada", go: "olvidar" },
                  { t: "«No. Lo que pasó, pasó. Lo cargo.»", go: "negarte" }] },
      usted: { say: [["desmemoria", "A mi madre. Murió en la fila del Fondo, el último invierno. Me acuerdo de que existió. No me acuerdo de su cara. La cambié por poder dormir."],
                     ["desmemoria", "Por eso trabajo aquí. Que nadie sufra lo que yo sufrí. Y a veces pienso que lo que sufrí era lo único que me quedaba de ella."]], back: "a" },
      olvidar: { say: [[null, "Te asomas. Respiras hondo. La sombra es fría y huele a tierra mojada. Piensas en algo de antes, algo que te dolió."],
                       [null, "Cuando subes, no sabes qué era. Sabes que había algo. En el Libro, una página tiene las letras borrosas, como si alguien les hubiera echado agua."],
                       ["desmemoria", "Ya está. ¿Se siente más liviano? La mayoría dice que sí. Algunos vuelven al mes, a preguntarme qué olvidaron. Yo no sé. Nadie sabe."]], end: { xp: 14, heal: 0.1, flag: "m6_olvidoPropio" } },
      negarte: { say: [["desmemoria", "Lo carga. Bueno. Qué cosa rara. La mayoría paga por no cargar."],
                       [null, "Mira la sombra un rato largo."],
                       ["desmemoria", "Yo también lo cargaría, si pudiera volver atrás. Pero ya no sé qué cargaría. Ese es el problema del pozo: no deja arrepentirse bien."]], end: { xp: 16, flag: "m6_recuerdas" } },
    } },

    "e6-noctambula": { kind: "dialogo", need: { era: 6, layer: 1 }, who: { noctambula: "Reina Noctámbula" }, start: "a", nodes: {
      a: { say: [[null, "En la sala más honda de la Corte Velada, detrás de siete cortinas de humo, una mujer joven con un velo largo cuenta monedas en una mesa de piedra. Tiene ojeras de no dormir."],
                 ["noctambula", "Soy Noctámbula. Reina de la Corte, nieta de Calígine, y por la sangre, de Lóbrego. La Corte ya perdió su tierra una vez. No va a perderla otra."],
                 ["noctambula", "Vendo olvido. No lo invento: la sombra estaba ahí. Yo solo puse una cola y un precio. Si no lo vendo yo, lo vende cualquiera, más caro y sin cuidado."]],
           opts: [{ t: "«La Crónica culpó a la Corte. ¿Vende olvido para que se olvide eso?»", go: "culpa", cNeed: "m3_culpaCorte" },
                  { t: "«La Crónica culpó a las Casas. ¿Y la Corte?»", go: "casas", cNeed: "m3_culpaCasas" },
                  { t: "«¿Qué guarda la Corte que nadie sabe?»", go: "secreto", once: true },
                  { t: "«Prometo no contar lo que me diga.»", go: "prometer" },
                  { t: "«Dígale a todos lo que sabe.»", go: "pedir" },
                  { t: "Irte sin prometer nada", go: "irte" }] },
      culpa: { say: [["noctambula", "Usted lo dice como si fuera malo. La Crónica nos culpó de una Raíz que despertaron todos. Tres generaciones cargando eso. ¿Por qué no íbamos a querer olvidarlo?"],
                     ["noctambula", "Lo que me molesta no es que lo olviden. Es que lo olviden y nos sigan mirando igual. El odio se queda aunque se vaya el motivo."]], back: "a" },
      casas: { say: [["noctambula", "Las Casas cargaron la culpa, sí. Y son las que más pagan por olvidarla. Vienen de noche, con capucha. Les cobro el doble."],
                     ["noctambula", "No es venganza. Es que la culpa de ellos pesa más, así que el pozo trabaja más. Eso digo yo."]], back: "a" },
      secreto: { say: [["noctambula", "Un secreto. Lo sabe cada reina, y ninguna lo dijo. Ya no sirve para nada, pero se guarda. Así son los secretos de la Corte: se guardan porque se guardaron."],
                       ["noctambula", "Si me promete no contarlo, se lo digo. Si no, me lo llevo como mi abuela."]], back: "a" },
      prometer: { say: [[null, "Noctámbula se levanta el velo un poco. Tiene los ojos rojos."],
                        ["noctambula", "Lo que se olvida en el pozo no desaparece. Baja a la Raíz. La Raíz lo guarda todo. Cada recuerdo que vendemos, la Raíz lo carga, y se olvida un poco de sí misma."],
                        ["noctambula", "Mi abuela lo sabía. Mi bisabuelo también. Y vendemos igual, porque la Corte tiene que comer. Ya está. Ahora usted también lo carga."]], end: { xp: 18, flag: "e6_secretoGuardado" } },
      pedir: { say: [["noctambula", "¿A todos? Usted no entiende a la Corte. Si digo un secreto, dejo de ser reina. La reina es la que guarda."],
                     [null, "Te mira mucho rato. Después vuelve a contar monedas."],
                     ["noctambula", "Vuelva cuando sepa lo que pide. Yo sí lo sé. Por eso no lo digo."]], end: { xp: 10, flag: "e6_secretoPedido" } },
      irte: { say: [[null, "Sales entre las siete cortinas. Detrás, el ruido de las monedas no para."]], end: { xp: 6 } },
    } },

    "e6-nombrada": { kind: "encuentro", need: { era: 6, layer: 1 }, who: { gualda: "Gualda, la Nombrada" }, start: "a", nodes: {
      a: { say: [[null, "A la entrada de la Hondonada, sentada en una piedra, una mujer de sombra con la ropa gastada saluda a todo el que pasa. A todos les dice lo mismo, como si no pudiera evitarlo."],
                 ["gualda", "Gualda de la Tercera Cortina, hija de Umbrío. Ese es mi nombre verdadero. Ya está, ya lo dije. Se lo digo a todo el mundo. No puedo callármelo."],
                 ["gualda", "En la Corte, el nombre verdadero no se dice. Quien lo sabe, sabe cómo hacerte olvidar. Mi hermano lo gritó en una pelea, delante de todos. Desde entonces me echaron. Una sombra con el nombre dicho es una puerta abierta."]],
           opts: [{ t: "«¿Por qué no puede callarlo?»", go: "porque", once: true },
                  { t: "Llevarla de vuelta a la Corte y hablar por ella", go: "volver" },
                  { t: "«Elija un nombre nuevo. Uno que nadie sepa.»", go: "nuevo" },
                  { t: "«Afuera de la Corte también se vive.»", go: "fuera" }] },
      porque: { say: [["gualda", "Cuando un nombre verdadero se dice en voz alta, se suelta. Ya no es tuyo solamente. Se te sale de la boca solo, como un hipo."],
                      ["gualda", "Las otras sombras dicen que es castigo de la Raíz. Yo creo que es otra cosa: que un nombre quiere que lo digan. Lo tuvimos callado mil años."]], back: "a" },
      volver: { say: [[null, "Vas con Gualda hasta la puerta de la Corte. Los guardias se tapan los oídos cuando ella dice su nombre. Hablas con el chambelán una hora entera."],
                      [null, "Al final la dejan entrar, por la puerta de atrás, a la cocina. No a la sala. A la cocina."],
                      ["gualda", "Gualda de la Tercera Cortina, hija de Umbrío, ayudante de cocina. Es más largo, pero es mío. Gracias. La Corte se acuerda de quién trae a los suyos de vuelta. Para bien y para mal."]], end: { xp: 18, flag: ["e6_gualdaVuelve", "u6_sombra"] } },
      nuevo: { say: [["gualda", "¿Un nombre nuevo? ¿Inventado?"],
                     [null, "Lo piensa mucho. Después se acerca y te dice algo al oído. Una palabra corta. No la repite."],
                     ["gualda", "Ese. Solo usted lo sabe. Si alguna vez lo digo en voz alta, sabré que me traicionó. Mientras tanto, sigo diciendo el otro. El otro ya no me hace nada."]], end: { xp: 16, flag: "e6_gualdaNueva" } },
      fuera: { say: [["gualda", "Afuera. Sí. Gualda de la Tercera Cortina, hija de Umbrío, que vive afuera. Suena a nada."],
                     [null, "Se levanta, se sacude la ropa y se va hacia el Prado. A cada persona que cruza le dice su nombre. Algunos le contestan con el suyo."],
                     [null, "Al rato, de lejos, la oyes reírse con alguien. Una risa de sombra, rara, corta."]], end: { xp: 12, flag: "e6_gualdaFuera" } },
    } },

    "e6-legajo": { kind: "encuentro", need: { era: 6, layer: 2 }, who: { legajo: "Legajo, archivero del Velo" }, start: "a", nodes: {
      a: { say: [[null, "En una galería seca de la Corte, entre estantes de rollos y cajas de papel, un hombre flaco con anteojos de vidrio ahumado copia a mano un rollo viejo. Tiene tinta hasta los codos."],
                 ["legajo", "Legajo, archivero del Velo. Copio todo lo que la gente viene a olvidar. Lo que se puede saber, por lo menos: quién vino, de dónde, qué cara traía. Los archivos tienen que sobrevivir al olvido. Si no, ¿quién se acuerda?"],
                 [null, "Al lado de la mesa, en el suelo, hay una página arrancada, arrugada como una bola. Legajo la tapa con el pie cuando ve que la miras."]],
           opts: [{ t: "«¿Qué dice esa página?»", go: "pagina", once: true },
                  { t: "Pedirle que te deje leer la página", go: "leer" },
                  { t: "«Copie los archivos para la Hondura. Que haya dos.»", go: "copiar" },
                  { t: "Dejar que la queme", go: "quemar" }] },
      pagina: { say: [["legajo", "Nada. Una cosa mía. Del invierno. Todos tenemos una página así."],
                      ["legajo", "La arranqué yo mismo. Podría ir al pozo, pero no: un archivero no olvida. Arranca. Es distinto. Lo arrancado sigue existiendo en algún lado."]], back: "a" },
      leer: { say: [[null, "Legajo duda. Después levanta el pie y te deja la página. La alisas en la mesa."],
                    [null, "Es una lista del último invierno. Nombres de sombras que pidieron mantas a la Corte y no las recibieron. Al final, con la letra de Legajo: «No las di. Me ordenaron. Pude haberlas dado igual»."],
                    ["legajo", "Ya está. Usted la leyó. Ahora existe en dos cabezas. La voy a volver a pegar en el rollo. Me cuesta, pero un archivo con páginas arrancadas no es un archivo."]], end: { xp: 18, flag: "e6_paginaLeida" } },
      copiar: { say: [["legajo", "¿Para la Hondura? ¿Para los que graban paredes? Nunca les mostramos nada."],
                      [null, "Pero acepta. Durante una semana bajas rollos a las Cuevas, de noche, en un saco. Los de la Hondura los copian en la piedra, palabra por palabra."],
                      ["legajo", "Dos archivos. Uno de papel, que se quema. Otro de piedra, que no. Si la reina se entera, me echa. Pero los nombres van a sobrevivir."]], end: { xp: 16, flag: "e6_archivoCopiado" } },
      quemar: { say: [[null, "Legajo acerca la página a la vela. Arde rápido. Las cenizas caen sobre el rollo que estaba copiando y las sopla."],
                      ["legajo", "Listo. Eso no pasó. No lo olvidé: lo quemé. Un archivero tiene derecho a una página. Una sola."]], end: { xp: 10, flag: "e6_paginaQuemada" } },
    } },

    "e6-comercio": { kind: "dialogo", need: { era: 6, layer: 3 }, who: { noctambula: "Reina Noctámbula", desmemoria: "Desmemoria, del pozo" }, start: "a", nodes: {
      a: { say: [[null, "La reina te recibe en la cueva de los pozos, de noche, sin cola. Desmemoria está a su lado, con las manos atrás."],
                 ["noctambula", "Usted anduvo por todo el Claro. Vio lo que hace el pozo. Le ofrezco una cosa: el olvido de la Corte, para lo que quiera."],
                 ["noctambula", "El Prado y el Barrio se odian desde el invierno. Las Mareas y el Fondo, también. Si los traigo a los pozos a todos juntos, olvidan el odio. Una tarde. Gratis. A cambio, la Corte queda con su tierra para siempre, por ley."]],
           opts: [{ t: "«¿Qué pasa con lo que olvidan, abajo?»", go: "abajo", once: true },
                  { t: "«Lo voy a denunciar. Todos van a saber qué hace el pozo.»", go: "denunciar" },
                  { t: "«Hágalo. Que olviden el odio.»", go: "usar" },
                  { t: "«Le compro la política: que la Corte deje de vender.»", go: "comprar" }] },
      abajo: { say: [["noctambula", "Baja. Ya se lo dije, o se lo dirán. La Raíz lo guarda. Con cada odio que se olvida, la Raíz se olvida un poco más del pacto."],
                     ["desmemoria", "Mi señora. Usted nunca lo dijo en voz alta."],
                     ["noctambula", "Lo digo ahora. El olvido no es gratis. Pero el odio tampoco."]], back: "a" },
      denunciar: { say: [[null, "Al día siguiente lo cuentas en el Prado, en el Cráter, en el Bosque. Que lo que se olvida baja a la Raíz. Que la Corte lo sabía."],
                         [null, "Las colas se achican. Una semana después, casi no viene nadie. La Corte se queda sin monedas. La gente vuelve a sus casas cargando lo que iba a olvidar."],
                         ["noctambula", "Bien. Ahora el Claro recuerda todo, y la Corte tiene hambre. Usted eligió por mi pueblo y por el suyo. Mi pueblo no lo va a olvidar. Y no hay pozo que lo cure."]], end: { xp: 18, flag: "m6_olvidoDenunciado" } },
      usar: { say: [[null, "Una tarde, la cola es de dos pueblos. Gente del Prado y del Barrio, codo con codo, sin mirarse. Uno por uno se asoman al pozo."],
                    [null, "Cuando suben, se miran. No saben por qué estaban serios. Alguien se ríe. Esa noche comen en la misma plaza."],
                    ["desmemoria", "Funcionó. Funcionó. Nunca vi a nadie subir sonriendo."],
                    ["noctambula", "Y nadie va a recordar por qué se odiaban. Tampoco lo que aprendieron odiándose. Así es el trato."]], end: { xp: 16, flag: "m6_odioOlvidado" } },
      comprar: { say: [["noctambula", "¿Comprar? ¿Con qué?"],
                       [null, "Le ofreces lo que tienes: tus monedas, tu palabra en el Corazón, que la Corte tenga voz cuando se hable de la tierra."],
                       ["noctambula", "Su palabra. Bien. La Corte deja de vender. Los pozos se tapan con piedra. A cambio, cuando los pueblos se junten, la Corte se sienta en la primera fila. Y no se discute su tierra."],
                       ["desmemoria", "¿Y la gente que viene mañana, mi señora? ¿Con qué duerme?"],
                       ["noctambula", "Con lo que tiene. Como antes. Como nosotros."]], end: { xp: 14, flag: "m6_politicaComprada" } },
    } },

    "e6-verso": { kind: "dialogo", need: { era: 6, layer: 3 }, who: { legajo: "Legajo, archivero del Velo", gualda: "Gualda, la Nombrada" }, start: "a", nodes: {
      a: { say: [[null, "Legajo te manda a llamar con un chico de la Corte. Lo encuentras en la galería de los archivos con Gualda, que está sentada en una caja, muy quieta."],
                 ["legajo", "Encontré algo en los rollos más viejos, de antes del primer exilio. Un verso. El noveno. El que no está en la nana. Dice cómo termina el pacto."],
                 ["legajo", "Si lo copio, alguien lo va a vender en el pozo. Si lo quemo, se pierde. Hay que guardarlo en algún lado que no se pueda olvidar ni vender."],
                 ["gualda", "Gualda de la Tercera Cortina, hija de Umbrío. Perdón. Escúchenme: un nombre verdadero no se olvida en el pozo. Es lo único que no se va. Si el verso se esconde dentro de un nombre, nadie lo saca."]],
           opts: [{ t: "«¿Qué dice el verso?»", go: "dice", once: true },
                  { t: "Esconder el verso en un nombre verdadero", go: "nombre" },
                  { t: "Contárselo a todos, para que nadie lo pueda vender", go: "todos" }] },
      dice: { say: [["legajo", "No lo entiendo bien. Habla de la Raíz y de quien la cuida. De lo que se le debe. Dice que el pacto no se paga con un canto: se paga con algo que se recuerda."],
                    ["legajo", "Lo demás no lo leo. La tinta está vieja. O yo estoy viejo. Las dos cosas."]], back: "a" },
      nombre: { say: [["gualda", "El mío ya se dijo. No sirve. Hace falta uno que nadie haya oído."],
                      [null, "Legajo trae a su nieta, una niña de sombra de seis años. Todavía no tiene nombre verdadero: en la Corte se da a los siete. Legajo escribe el verso en un papel, se lo lee al oído y quema el papel."],
                      ["legajo", "Su nombre va a ser el verso. Cuando lo diga, lo va a decir. Mientras lo calle, lo guarda. Tiene que vivir escondida. Toda la vida. Y sus hijos después."],
                      ["gualda", "Pobre. Pobre de ella. Yo sé lo que pesa un nombre."]], end: { xp: 20, flag: "m6_versoNombre" } },
      todos: { say: [[null, "Esa semana el verso se lee en voz alta en la plaza del Prado, en la Forja, en la puerta de la Corte. Legajo lo lee con la voz temblando. Lo copian en paredes, en tablillas, en mantas."],
                     [null, "Al mes, el verso se canta en las tabernas con otra música. Algunos le cambian las palabras. Nadie sabe ya cuál es el de verdad."],
                     ["legajo", "No lo pueden vender. Lo tiene todo el mundo. Pero lo tiene todo el mundo distinto. No sé si lo salvé o lo rompí."]], end: { xp: 16, flag: "m6_versoTodos" } },
    } },
  });

  /* ---------- Prado Aurora: los vecinos que se odian sin motivo, las Casas y el culpable que olvidó ---------- */
  add("aurora", {
    "e6-vecinos": { kind: "encuentro", need: { era: 6, layer: 1 }, who: { rastrojo: "Rastrojo, del Barrio" }, start: "a", nodes: {
      a: { say: [[null, "En una calle del Barrio, dos casas tienen las puertas pintadas de colores distintos y una cerca de palos entre las dos. En cada ventana hay alguien mirando a la otra con mala cara."],
                 ["rastrojo", "Rastrojo, del Barrio. Esa es mi casa, la azul. Los de enfrente son los de la verde. No nos hablamos desde el invierno. No me acuerdo por qué. Fui al pozo. Ellos también."],
                 ["rastrojo", "Lo raro es que el enojo no se fue. Me levanto y los odio. No sé de qué. Es como tener hambre sin estómago."]],
           opts: [{ t: "«¿Nadie se acuerda de lo que pasó?»", go: "nadie", once: true },
                  { t: "Buscar en las Cuevas qué pasó entre las dos casas", go: "buscar" },
                  { t: "Sentarlos a comer en la misma mesa, sin explicar nada", go: "mesa" },
                  { t: "«Si no se acuerdan, no hay nada que arreglar.»", go: "dejar" }] },
      nadie: { say: [["rastrojo", "Los chicos no. Eran chicos. Mi abuela se acuerda, pero no quiere decir. Dice que si yo pagué por olvidar, no me lo va a devolver gratis."],
                     ["rastrojo", "Así que vivo odiando algo que mi abuela sabe y yo no. Raro, ¿no?"]], back: "a" },
      buscar: { say: [[null, "En las Cuevas, la Hondura graba todo. Encuentras las dos casas en una pared, con letra chica: «Invierno. La verde escondió leña. La azul la robó. Murió un chico de la verde. Murió una vieja de la azul»."],
                      [null, "Se lo lees a Rastrojo. Se queda callado mucho rato."],
                      ["rastrojo", "Ah. Era eso. Ahora sé por qué los odio. Y sé por qué ellos me odian. No sé si es mejor. Es más pesado. Pero por lo menos es mío."]], end: { xp: 16, flag: "e6_odioSabido" } },
      mesa: { say: [[null, "Pones una mesa en el medio de la calle, encima de la cerca caída. Traes pan, sopa y dos sillas. Convences a Rastrojo. Convences a la vecina de la verde, a la tercera vez."],
                    [null, "Comen sin hablar. Después ella le pide la sal. Él se la pasa. Al final, él le pregunta si ella se acuerda. Ella dice que no."],
                    ["rastrojo", "Ninguno se acuerda. Y comimos igual. A lo mejor eso alcanza. A lo mejor el Barrio se arregla así: comiendo con quien no recuerdas por qué odias."]], end: { xp: 18, flag: ["e6_mesaJunta", "u6_barrio"] } },
      dejar: { say: [["rastrojo", "Nada que arreglar. Sí. Eso me digo."],
                     [null, "Vuelve a su ventana. Enfrente, la vecina vuelve a la suya. Se miran con mala cara, sin saber por qué, como cada mañana."]], end: { xp: 8, flag: "e6_odioQueda" } },
    } },

    "e6-casas": { kind: "encuentro", need: { era: 6, layer: 1 }, who: { tojo: "Tojo, de las Casas del Farol" }, start: "a", nodes: {
      a: { say: [[null, "En la casa más grande de las Casas del Farol hay un salón lleno de retratos. A la mitad les taparon la cara con tela negra. Un joven bien vestido los descuelga uno por uno."],
                 ["tojo", "Tojo, de las Casas del Farol. Estoy ordenando la historia de la familia. Lo que pasó en el invierno lo pagamos para olvidarlo. Los retratos de esos años sobran. Los voy a quemar."],
                 ["tojo", "Una familia sin vergüenza es una familia que puede volver a mandar. Eso dice mi tío. Yo no sé. Pero obedezco."]],
           opts: [{ t: "«¿Quiénes son los de la tela negra?»", go: "quienes", once: true },
                  { t: "Ayudarlo a escribir la historia de las Casas como fue", go: "escribir" },
                  { t: "Ayudarlo a quemar los retratos", go: "quemar" },
                  { t: "Guardar un retrato a escondidas", go: "guardar" }] },
      quienes: { say: [["tojo", "No sé. Por eso los tapamos. Gente de la familia que hizo algo en el invierno. Mi tío dice que es mejor no saber qué."],
                       ["tojo", "Uno de ellos tiene mi nariz. Es raro mirar a alguien que tiene tu nariz y no saber qué hizo."]], back: "a" },
      escribir: { say: [[null, "Pasan tres días en la biblioteca de la familia. Encuentran cartas, cuentas, una lista de leña. Las Casas guardaron leña mientras el Barrio quemaba sillas. Está todo escrito, con la letra de un abuelo."],
                        [null, "Tojo escribe la historia de las Casas en un libro nuevo. Lo de antes, lo del invierno, lo de ahora. No tapa nada. Al terminar, saca la tela negra de los retratos."],
                        ["tojo", "Mi tío me va a matar. Bueno, no. Me va a desheredar. Las Casas van a tener que mirarse la cara. Por lo menos ahora sabemos a quién nos parecemos."]], end: { xp: 18, flag: ["e6_historiaCasas", "u6_luz"] } },
      quemar: { say: [[null, "Los retratos arden en el patio, uno encima del otro. La pintura huele a aceite viejo. Tojo mira el fuego sin parpadear."],
                      ["tojo", "Ya está. Nadie hizo nada. Las Casas están limpias. Mañana mi tío firma la petición para volver al Concejo del Prado."]], end: { xp: 10, flag: "e6_retratosQuemados" } },
      guardar: { say: [[null, "Mientras Tojo saca los retratos al patio, escondes uno chico bajo el abrigo. El de la nariz."],
                       [null, "Esa noche lo miras a la luz de una vela. Es un hombre joven, con una llave en la mano. Atrás, en el cuadro, se ve una puerta cerrada y nieve."],
                       [null, "Alguien en las Casas va a querer saber algún día. El retrato espera."]], end: { xp: 14, flag: "e6_retratoGuardado" } },
    } },

    "e6-tojo": { kind: "dialogo", need: { era: 6, layer: 2 }, who: { tojo: "Tojo, de las Casas del Farol", rastrojo: "Rastrojo, del Barrio" }, start: "a", nodes: {
      a: { say: [[null, "En la plaza del Prado hay gente alrededor de Tojo. Rastrojo lo tiene agarrado del brazo. Una vieja del Barrio grita algo que no se entiende."],
                 ["rastrojo", "La vieja dice que él cerró la puerta de su casa en el invierno con una familia del Barrio afuera, en la nieve. Tres murieron. Tenía la llave en la mano. Ella lo vio."],
                 ["tojo", "No me acuerdo. Lo juro. Fui al pozo después del invierno. No sé qué olvidé. Si fue eso... no sé quién era yo. Ese no soy yo."]],
           opts: [{ t: "«¿Hay pruebas?»", go: "pruebas", once: true },
                  { t: "El retrato: es un hombre con una llave, frente a una puerta en la nieve", go: "retrato", cNeed: "e6_retratoGuardado" },
                  { t: "«Lo hizo. Que pague, se acuerde o no.»", go: "castigar" },
                  { t: "«Ya no es esa persona. Perdónenlo.»", go: "perdonar" },
                  { t: "«Que recuerde. La Hondura lo tiene grabado.»", go: "recordar" }] },
      pruebas: { say: [["rastrojo", "La vieja. Y la Hondura grabó el nombre de los tres muertos. No el de quién cerró la puerta. Nadie se acuerda de eso más que ella."],
                       ["tojo", "Y yo no me acuerdo de nada. ¿Cómo se defiende alguien de algo que no sabe si hizo?"]], back: "a" },
      retrato: { say: [[null, "Sacas el retrato de abajo del abrigo. Tojo lo mira. Es él, más joven, con la llave."],
                       ["tojo", "Esa es la puerta de mi casa. Ese soy yo. No me acuerdo de haber posado. No me acuerdo de nada."],
                       [null, "La vieja del Barrio deja de gritar. Mira el cuadro. Llora."]], back: "a" },
      castigar: { say: [[null, "El Prado lo juzga en la plaza. Lo condenan a cortar leña para el Barrio durante diez inviernos. Tojo acepta sin pelear."],
                        ["tojo", "Diez inviernos por algo que no recuerdo. Está bien. Ellos sí lo recuerdan. Lo justo se mide con la memoria del que perdió, no con la mía."],
                        ["rastrojo", "La justicia del Claro mira el acto. No a la persona. Que sea así. Si no, todos van a ir al pozo antes de cada crimen."]], end: { xp: 16, flag: "m6_castigoActo" } },
      perdonar: { say: [["rastrojo", "¿Perdonarlo? ¿Así, sin más?"],
                        [null, "Discuten toda la tarde. Al final, la vieja del Barrio se acerca a Tojo y le toca la cara."],
                        [null, "«No sé quién eres. El que cerró la puerta ya se murió. Tú estás vivo»."],
                        ["tojo", "Gracias. No sé qué hacer con esto. Nadie me dio nunca algo que no merezco."],
                        ["rastrojo", "Así quedó. La justicia del Claro mira a la persona, no el acto. El que va al pozo se lava. Ya van a ver adónde lleva eso."]], end: { xp: 14, flag: "m6_perdonPersona" } },
      recordar: { say: [[null, "Llevas a Tojo a las Cuevas. Le lees la pared, despacio: los tres nombres, la noche, la nieve. Le cuentas lo que dice la vieja."],
                        [null, "No vuelve el recuerdo. El pozo no devuelve. Pero Tojo se sienta en el suelo de la cueva y llora como si le hubiera vuelto."],
                        ["tojo", "No me acuerdo. Pero ahora lo sé. Es peor. Es mejor. Voy a vivir con eso. A lo mejor eso es recordar: cargar algo que no te acuerdas, porque otros sí."]], end: { xp: 18, flag: "m6_recuerdoForzado" } },
    } },
  });

  /* ---------- Las otras zonas: un pueblo por zona, cada uno con su olvido ---------- */
  add("crater", {
    "e6-deudas": { kind: "encuentro", need: { era: 6, layer: 1 }, who: { recaudo: "Recaudo, cobrador del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "En la puerta de la Forja hay una fila de obreros con las gorras en la mano. Un hombre gordo con una tablilla los llama uno por uno."],
                 ["recaudo", "Recaudo, cobrador del Gremio. Este debe tres sacos de carbón del invierno. Dice que no se acuerda. Fue al pozo. El Gremio no fue al pozo. El Gremio se acuerda de todo."],
                 ["recaudo", "Así que cobramos lo que el obrero olvidó. Más los intereses de olvidarlo. Si no, cualquiera va al pozo y deja de deber."]],
           opts: [{ t: "«¿Usted se acuerda del invierno?»", go: "usted", once: true },
                  { t: "«Rompa las tablillas del invierno. Que empiecen de nuevo, los dos lados.»", go: "romper" },
                  { t: "«Que paguen la deuda, pero sin intereses.»", go: "medio" },
                  { t: "«Es justo. Que paguen.»", go: "pagar" }] },
      usted: { say: [["recaudo", "Me acuerdo. Yo repartía carbón. Le fiaba a todo el mundo. Si no fiaba, se morían. El Gremio me dijo que anotara. Anoté."],
                     ["recaudo", "No soy malo. Soy el que anotó. Es distinto. O eso me digo."]], back: "a" },
      romper: { say: [["recaudo", "¿Romperlas? ¿Y lo que el Gremio fió?"],
                      [null, "Lo discutes con él, con los obreros, con el maestro del Gremio. Al final se rompen las tablillas del invierno en la plaza, a martillazos. Los obreros aplauden. El Gremio pierde mucho."],
                      ["recaudo", "Que nadie deba lo que no recuerda. Y que nadie cobre lo que no puede probar. Me quedo sin trabajo. Pero esta noche duermo."]], end: { xp: 18, flag: ["e6_tablillasRotas", "u6_fuego"] } },
      medio: { say: [[null, "Recaudo borra los intereses con el pulgar mojado. Los obreros pagan lo que deben, poco a poco, en carbón."],
                     ["recaudo", "Lo justo, y nada más. Nadie se queda contento. Así se sabe que es justo."]], end: { xp: 12, flag: "e6_deudaSinInteres" } },
      pagar: { say: [[null, "La fila avanza. Un obrero paga con sus herramientas. Otro con su lugar en la fila del pan. Uno se va sin decir nada, hacia la Hondonada."],
                     ["recaudo", "Va al pozo. A olvidar la deuda nueva. Vuelve en un mes. Así se ganan los pozos y el Gremio. Los dos."]], end: { xp: 8, flag: "e6_deudaCobrada" } },
    } },
  });

  add("forest", {
    "e6-silencio": { kind: "encuentro", need: { era: 6, layer: 1 }, who: { acebo: "Acebo, del Concejo del Musgo" }, start: "a", nodes: {
      a: { say: [[null, "En el claro del Concejo, la gente está sentada en el suelo, en silencio, con los ojos cerrados. Es el Largo Silencio, el de siempre. Pero nadie escucha el bosque: todos tienen tapones de musgo en los oídos."],
                 ["acebo", "Acebo, del Concejo. Antes el Silencio era para oír la Raíz. Ahora es para no oír nada. La gente se sienta aquí a olvidar sin pagar. Callando mucho, se olvida algo. No tanto como en el pozo, pero sale gratis."],
                 ["acebo", "Y el bosque habla igual. Nadie lo oye. Los árboles se enferman y nadie se entera."]],
           opts: [{ t: "«¿Qué dice el bosque?»", go: "dice", once: true },
                  { t: "Sacarte el musgo y escuchar por todos", go: "escuchar" },
                  { t: "Proponerle al Concejo un Silencio con los oídos abiertos", go: "abrir" },
                  { t: "Sentarte a olvidar con ellos", go: "olvidar" }] },
      dice: { say: [["acebo", "No sé. Yo también tengo musgo. Me lo saco a veces y oigo un crujido, muy hondo. Me lo vuelvo a poner. Me da miedo."],
                    ["acebo", "Mi abuelo decía que la Raíz habla por los árboles cuando le duele algo. Ahora le duele. Y nosotros con los oídos tapados."]], back: "a" },
      escuchar: { say: [[null, "Te sacas el musgo. Te sientas. El bosque cruje. Después, por debajo del crujido, oyes algo como agua corriendo bajo la tierra, y voces muy lejos, muchas, hablando a la vez."],
                        [null, "Son recuerdos. Los que bajaron por el pozo. La Raíz los está repitiendo, sin orden, como quien habla dormido."],
                        ["acebo", "¿Qué oye? Tiene cara de oír algo. No me lo diga. O sí. Dígamelo mañana."]], end: { xp: 16, flag: "e6_raizOida" } },
      abrir: { say: [[null, "Hablas en el Concejo. Te cuesta. Al final, Acebo propone un Silencio nuevo: un día por semana, sin musgo, para escuchar."],
                     [null, "El primer día van seis. El segundo, veinte. Algunos lloran al oír. Otros se van corriendo. Los que quedan, anotan lo que oyen en hojas."],
                     ["acebo", "El Bosque vuelve a escuchar. Duele. Antes dolía y no sabíamos por qué. Ahora duele y sabemos. Es mejor, creo."]], end: { xp: 18, flag: ["e6_silencioAbierto", "u6_planta"] } },
      olvidar: { say: [[null, "Te sientas con ellos, con musgo en los oídos. Pasa una hora. Pasan dos. No olvidas nada en particular. Pero cuando te levantas, tardas en recordar por qué viniste."],
                       ["acebo", "Eso. Así es. Se pierde poco, pero se pierde. Y nadie sabe qué."]], end: { xp: 8, flag: "e6_silencioHueco" } },
    } },
  });

  add("heights", {
    "e6-canciones": { kind: "encuentro", need: { era: 6, layer: 1 }, who: { redoble: "Redoble, tamborero" }, start: "a", nodes: {
      a: { say: [[null, "En la plaza de la cumbre, un hombre con las manos grandes toca un tambor viejo. Los pueblos de alrededor contestan. Pero los versos que tocan no son mensajes: son canciones, mezcladas, que ya nadie sabe qué decían."],
                 ["redoble", "Redoble, tamborero. Me enseñaron los golpes de chico. «Estamos vivos, nos falta», «el hielo que se corta trae frío», el verso de los muertos. Los toco todos. Nadie recuerda para qué eran."],
                 ["redoble", "La gente del valle sube a bailarlos. Dicen que son lindos. Uno es el verso de los muertos. Lo bailan en las bodas."]],
           opts: [{ t: "«¿Nadie anotó qué querían decir?»", go: "anotar", once: true },
                  { t: "Ayudarle a escribir lo que dice cada verso, con los viejos", go: "escribir" },
                  { t: "«Que los bailen. Una canción no tiene dueño.»", go: "bailar" },
                  { t: "«No toque el verso de los muertos en las bodas.»", go: "prohibir" }] },
      anotar: { say: [["redoble", "Los libros de mensajes. Algunos se quemaron, en el invierno. Otros se mojaron. Quedaron treinta, dicen, en algún lado. Nadie los busca."],
                      ["redoble", "La mujer que me enseñó tenía las manos hinchadas. Me dijo que si me tocaba llevar algo que no quería, agregara dos golpes al final. No me dijo qué quería decir. Lo hago igual."]], back: "a" },
      escribir: { say: [[null, "Durante un mes subes a la cumbre cada tarde. Redoble toca cada verso, y los viejos de los Altos dicen lo que se acuerdan. Escribes todo en un cuaderno."],
                        [null, "El verso de los muertos lo reconoce una vieja de cien años. Lo inventó el pueblo del este, dice, una noche que no llegó el trineo."],
                        ["redoble", "Ahora sé lo que toco. Pesa. Pero cuando toco «estamos vivos, nos falta», ya no lo toco para bailar. Lo toco para alguien. Los Altos se acuerdan de sí mismos."]], end: { xp: 18, flag: ["e6_versosEscritos", "u6_altos"] } },
      bailar: { say: [["redoble", "Sin dueño. Sí. Así es más fácil."],
                      [null, "Esa noche hay una boda en la plaza. Redoble toca el verso de los muertos. Los novios bailan. Se ríen."]], end: { xp: 10, flag: "e6_versosBailados" } },
      prohibir: { say: [["redoble", "¿Por qué no? Si nadie se acuerda de qué es."],
                        [null, "Le cuentas lo que es. Redoble deja de tocar. Mira el tambor."],
                        ["redoble", "Lo toqué en mi boda. Mi mujer lo bailó. No le voy a decir. Pero no lo toco más en las bodas. Lo toco cuando se muere alguien. Como era."]], end: { xp: 14, flag: "e6_versoMuertos" } },
    } },
  });

  add("lake", {
    "e6-nadar": { kind: "encuentro", need: { era: 6, layer: 1 }, who: { ondina: "Ondina, de las Mareas" }, start: "a", nodes: {
      a: { say: [[null, "En la orilla del Lago Espejo, una mujer de las Mareas mete a un grupo de chicos en el agua hasta la cintura. Los chicos tiemblan. Ninguno sabe flotar."],
                 ["ondina", "Ondina, de las Mareas. Mis padres sabían nadar. Mis abuelos nacieron en barcas. En el invierno el lago se congeló, y se ahogaron muchos cuando se rompió el hielo. Después todos fueron al pozo a olvidarlo."],
                 ["ondina", "Y con el miedo, olvidaron el agua. Ya nadie sabe nadar. Las Mareas sin agua. Yo aprendí sola, a los treinta, tragando lago."]],
           opts: [{ t: "«¿Por qué olvidaron también nadar?»", go: "porque", once: true },
                  { t: "Meterte al agua y enseñar con ella", go: "ensenar" },
                  { t: "Buscar a un viejo que todavía recuerde", go: "viejo" },
                  { t: "«Mejor que no se metan. Si no saben, no se ahogan.»", go: "tierra" }] },
      porque: { say: [["ondina", "Porque el pozo no corta fino. Uno piensa «el hielo roto, mi hermano en el agua» y se lleva todo lo que está pegado. El agua estaba pegada."],
                      ["ondina", "Lo que se olvida no se va solo. Se lleva a los vecinos."]], back: "a" },
      ensenar: { say: [[null, "Te metes al agua fría. Ondina sostiene a un chico de la espalda; tú, a otro. Les enseñan a soltar el aire despacio, a abrir los brazos."],
                       [null, "Al tercer día, una niña flota sola diez segundos. Grita de alegría y se hunde. La sacan riéndose."],
                       ["ondina", "Diez segundos. Es más de lo que mi madre podía hacer al final. Las Mareas vuelven al agua de a un chico por vez. Y se acuerdan de quién les enseñó."]], end: { xp: 18, flag: ["e6_ninosNadan", "u6_agua"] } },
      viejo: { say: [[null, "Encuentras a un viejo de las Mareas que nunca fue al pozo. Dice que no quiso, que prefería tener pesadillas. Sabe nadar."],
                     [null, "Se mete al lago, flaco, despacio. Los chicos lo miran como a un pez raro. Les enseña tres brazadas antes de cansarse."],
                     ["ondina", "Él se acuerda de todo. Del hielo, de los muertos. Y por eso sabe nadar. No sé qué pensar de eso."]], end: { xp: 14, flag: "e6_viejoNada" } },
      tierra: { say: [["ondina", "Si no saben, no se ahogan. Eso dicen los padres. Y se quedan en la orilla mirando el agua como un enemigo."],
                      [null, "Saca a los chicos del agua. Se secan al sol. Uno mira el lago con ganas. Su madre lo agarra de la mano."]], end: { xp: 8, flag: "e6_orillaSeca" } },
    } },
  });

  add("caves", {
    "e6-grabar": { kind: "encuentro", need: { era: 6, layer: 1 }, who: { mica: "Mica, de la Hondura" }, start: "a", nodes: {
      a: { say: [[null, "Las paredes de las Cuevas están llenas de letras, de arriba abajo. Nombres, fechas, frases chicas. Una mujer con el pelo gris corto graba con un punzón en el último pedazo libre, a la altura de los tobillos."],
                 ["mica", "Mica, de la Hondura. De chica pegaba la oreja a la pared para oír los golpes de abajo. Ahora le escribo. Todo lo que los otros pueblos van a olvidar al pozo, la Hondura lo graba antes. Vienen a contármelo y lo escribo."],
                 ["mica", "Ya no queda pared. Y cada día vienen más. Algunos me piden que borre lo que escribí. No borro nunca."]],
           opts: [{ t: "«¿Por qué la Hondura no olvida?»", go: "porque", once: true },
                  { t: "«Abran galerías nuevas. Que la pared no se termine.»", go: "cavar" },
                  { t: "«Borre lo que le pidan borrar.»", go: "borrar" },
                  { t: "Ayudarla a grabar lo de hoy", go: "ayudar" }] },
      porque: { say: [["mica", "Porque la pared se acuerda igual. La piedra repite lo que oye. Si la Hondura olvida, la pared sigue hablando, y nadie entiende qué dice."],
                      ["mica", "Y porque alguien tiene que acordarse. Si todo el Claro olvida, el Claro no sabe quién es. Es un trabajo feo. Lo hacemos nosotros."]], back: "a" },
      cavar: { say: [[null, "La Hondura abre dos galerías nuevas, lisas, solo para escribir. Los picadores trabajan gratis. Dicen que es para sus nietos."],
                     [null, "Mica graba la primera línea en la pared nueva: «Aquí empieza lo que el Claro no quiso saber»."],
                     ["mica", "Pared nueva. Para treinta años más. Después, otra. La Hondura no se cansa de piedra. Gracias por pensarlo con nosotros."]], end: { xp: 18, flag: ["e6_galeriasNuevas", "u6_piedra"] } },
      borrar: { say: [["mica", "¿Borrar? Si borro, ¿quién se acuerda?"],
                      [null, "Al final borra uno. El de un hombre que vino llorando: pegó a su hijo en el invierno, y el hijo se murió de fiebre. Mica raspa la piedra hasta que no queda nada."],
                      ["mica", "Uno. Lo borré. Él va a dormir. El chico ya no está en ningún lado. Ni en la pared. No sé si eso es piedad o es matarlo otra vez."]], end: { xp: 10, flag: "e6_paredBorrada" } },
      ayudar: { say: [[null, "Toda la tarde, la gente viene y cuenta. Tú escuchas y dictas. Mica graba. Una mujer cuenta que robó pan. Un chico, que no compartió una manta."],
                      ["mica", "Usted escucha bien. No pone cara. La gente cuenta más cuando nadie pone cara."]], end: { xp: 14, flag: "e6_grabadoHoy" } },
    } },
  });

  add("deep", {
    "e6-sonadores": { kind: "encuentro", need: { era: 6, layer: 1 }, who: { sopor: "Sopor, soñadora del Fondo" }, start: "a", nodes: {
      a: { say: [[null, "En una sala del Fondo Blanco, en camas de hielo, duermen veinte soñadores. Se mueven. Lloran dormidos. Una mujer despierta, con la cara mojada, se sienta en su cama."],
                 ["sopor", "Sopor, soñadora. Soñé con una familia que se moría en una puerta, en la nieve. No los conozco. Nadie del Fondo los conoce. Pero lloro por ellos cada noche."],
                 ["sopor", "Lo que se olvida en el pozo baja a la Raíz. Y la Raíz sueña. Y nosotros soñamos lo que sueña la Raíz. Somos los que recuerdan lo que nadie quiere."]],
           opts: [{ t: "«Después del Deshielo, ¿el Fondo sueña su propia hambre?»", go: "deshielo", cNeed: "m5_deshielo" },
                  { t: "«La regencia se quedó fuerte. ¿Qué sueña?»", go: "tumba", cNeed: "m5_tumba" },
                  { t: "«¿Cuánto tiempo se puede soñar eso?»", go: "cuanto", once: true },
                  { t: "«Cuente lo que sueña. A los que lo olvidaron.»", go: "contar" },
                  { t: "«Duerma sin soñar. Hay hierbas.»", go: "dormir" }] },
      deshielo: { say: [["sopor", "Sí. Y la de los demás. Soñamos a los que no comieron cuando se pudrió el granero. Algunos eran del Fondo. Otros, de los pueblos que nos odian por eso."],
                        ["sopor", "Es raro llorar por alguien que te odia. Nadie más lo hace. Por eso lo hacemos nosotros."]], back: "a" },
      tumba: { say: [["sopor", "La regencia no sueña. Duerme bien. Los que soñamos somos los de abajo. Soñamos las filas, las puertas cerradas, el frío que la Tumba terminó."],
                     ["sopor", "La Tumba terminó el invierno. No terminó el recuerdo. Ese bajó a la Raíz y vuelve por las noches."]], back: "a" },
      cuanto: { say: [["sopor", "Mi madre soñó cuarenta años. Se murió dormida, sonriendo. Yo creo que al final soñó algo lindo, algo que alguien olvidó de felicidad."],
                      ["sopor", "Casi nadie va al pozo a olvidar algo feliz. Pero a veces pasa. Esas noches son las mejores."]], back: "a" },
      contar: { say: [[null, "Sopor cuenta sus sueños en la puerta del Fondo, cada mañana, a quien quiera oír. Algunos se tapan los oídos. Otros se quedan."],
                      [null, "Una mañana, un hombre del Barrio la escucha y se pone pálido. Es su familia. La que soñó. La que él olvidó."],
                      ["sopor", "Se lo devolví. No el recuerdo: el dolor. Me odió un rato. Después me dio la mano. El Fondo sirve para algo otra vez."]], end: { xp: 18, flag: ["e6_suenosContados", "u6_escarcha"] } },
      dormir: { say: [[null, "Le consigues hierbas de la Seta para dormir sin sueños. Sopor las toma esa noche."],
                      [null, "A la mañana se despierta seca, descansada. Al lado, en otra cama, otro soñador llora el doble."],
                      ["sopor", "No sueño. Bien. Alguien lo sueña por mí. No se pierde: se pasa. Como todo en este Claro."]], end: { xp: 10, flag: "e6_suenoPasado" } },
    } },
  });

  /* ---------- Corazón del Claro: las estatuas sin dueño, las dos Estrellas y el final ---------- */
  add("heart", {
    "e6-estatuas": { kind: "encuentro", need: { era: 6, layer: 2 }, who: {}, start: "a", nodes: {
      a: { say: [[null, "En el Corazón hay tres estatuas. La de la cantora con dos voces, la de las dos figuras de hielo y seta, la del forjador con la escoria pegada. Un grupo de chicos juega a perseguirse entre ellas."],
                 [null, "Les preguntas quién las puso. No saben. Un viejo que pasa dice que siempre estuvieron. Otro dice que son de los antiguos, del tiempo de antes de los pueblos."],
                 [null, "Tu Libro, en cambio, recuerda. Algunas páginas. Lo sientes pesado en la mochila."]],
           opts: [{ t: "Contarles lo que dice el Libro de cada estatua", go: "contar" },
                  { t: "Dejar que los chicos inventen quiénes son", go: "inventar" },
                  { t: "Llevar a alguien de la Hondura a grabarlo en la base", go: "grabar" }] },
      contar: { say: [[null, "Te sientas con los chicos y les lees el Libro. La cantora, el Fuego, el pacto. Las dos voces del hielo y la seta. El forjador y su sed."],
                      [null, "Una niña pregunta si es verdad. Le dices que es lo que quedó escrito. Ella dice que eso no es lo mismo. Tiene razón."]], end: { xp: 16, flag: "e6_estatuasContadas" } },
      inventar: { say: [[null, "Los chicos inventan. La cantora es una reina que perdió un zapato. Las dos figuras son hermanos que se pelearon por una seta. El forjador es un gigante que comía piedras."],
                        [null, "Se ríen. Al rato, otros chicos repiten la historia como si fuera vieja. Dentro de diez años, alguien la va a escribir."]], end: { xp: 10, flag: "e6_estatuasInventadas" } },
      grabar: { say: [[null, "Un picador de la Hondura baja con punzón y martillo. Graba en la base de cada estatua lo que le dictas, en letra chica, que dure."],
                      [null, "Al terminar, se limpia el polvo de la cara."],
                      [null, "«Ahora la piedra se acuerda. La gente puede olvidar. La piedra no»."]], end: { xp: 16, flag: "e6_estatuasGrabadas" } },
    } },

    "e6-estrellas": { kind: "encuentro", need: { era: 6, layer: 1, flag: "m5_boda" }, who: {}, start: "a", nodes: {
      a: { say: [[null, "Esta noche, en el Corazón, la gente se separó en dos grupos. Los de la izquierda miran la Estrella vieja. Los de la derecha, la nueva, la que nació en la Boda."],
                 [null, "Cada grupo canta una versión distinta del pacto. Una dice que la cantora se dio a la Raíz. La otra dice que la Raíz se dio a la cantora. Se tapan los oídos unos a otros."],
                 [null, "Un hombre de cada grupo se acerca a ti. Los dos quieren lo mismo: que convenzas al otro grupo de ir al pozo a olvidar su versión."]],
           opts: [{ t: "«Las dos Estrellas vieron algo. Canten las dos versiones.»", go: "dos" },
                  { t: "Convencer a los de la Estrella nueva de olvidar su versión", go: "nueva" },
                  { t: "Convencer a los de la Estrella vieja de olvidar la suya", go: "vieja" }] },
      dos: { say: [[null, "Los juntas en el medio. Les propones cantar las dos, una después de la otra. Se niegan. Después, uno de la izquierda empieza. Uno de la derecha contesta con la otra."],
                   [null, "No suena bien. Suena a discusión. Pero nadie se va. En el cielo, las dos Estrellas brillan un poco más fuerte, o eso parece."]], end: { xp: 18, flag: "e6_dosVersiones" } },
      nueva: { say: [[null, "Los de la Estrella nueva van al pozo. Vuelven sin su versión. Miran el cielo y ven una Estrella que no saben qué significa."],
                     [null, "Queda una sola historia del pacto. Esa noche, la Estrella nueva parece más chica."]], end: { xp: 10, flag: "e6_versionNuevaOlvidada" } },
      vieja: { say: [[null, "Los de la Estrella vieja van al pozo. Vuelven sin su versión. La cantora ya no se dio a la Raíz: la Raíz se dio a ella. Es más linda la historia. Es más fácil."],
                     [null, "Esa noche, la Estrella vieja parpadea, como quien se queda sin palabra."]], end: { xp: 10, flag: "e6_versionViejaOlvidada" } },
    } },

    "e6-final": { kind: "dialogo", need: { era: 6, eraWin: "heart" }, first: true, once: true, who: { noctambula: "Reina Noctámbula", legajo: "Legajo, archivero del Velo", gualda: "Gualda, la Nombrada" }, start: "a", nodes: {
      a: { say: [[null, "La Raíz Velada cae, y de la grieta sale sombra, mucha, espesa, que sube como humo. Es todo lo que se olvidó en los pozos. Frente a las estatuas están la reina Noctámbula, Legajo y Gualda."],
                 ["noctambula", "Ahí está todo. Lo que vendimos. Si lo dejamos subir, cubre el Claro entero. Nadie va a recordar esta era. Ni el odio, ni el hambre, ni el pacto. Paz. Otra vez."],
                 ["legajo", "O se dicen los nombres. Todos. Los que la Corte guarda, los de los que vinieron al pozo, los de los muertos. La sombra no se lleva lo que se nombra. Sale la verdad, entera."],
                 ["gualda", "Gualda de la Tercera Cortina, hija de Umbrío. Perdón. Hay una tercera. Esconder el noveno verso en un nombre verdadero. Uno solo. Que alguien lo guarde, escondido, toda la vida. Pero para eso tienen que estar de acuerdo los nueve. Si no, no se protege a nadie."]],
           opts: [{ t: "«¿Qué pasa si sube la sombra?»", go: "q1", once: true },
                  { t: "«¿Qué pasa si se dicen todos los nombres?»", go: "q2", once: true },
                  { t: "«¿Qué pasa con quien guarde el verso?»", go: "q3", once: true },
                  { t: "Dejar que la sombra cubra el Claro", go: "velo" },
                  { t: "Decir en voz alta todos los nombres guardados", go: "nombres" },
                  { t: "Esconder el noveno verso en un nombre, con los nueve de testigos", go: "guardado", cNeed: "e6_nueve" }] },
      q1: { say: [["noctambula", "Paz. Nadie se odia, porque nadie recuerda por qué. La Corte conserva su tierra, porque nadie recuerda que la tenía. Y la Raíz... la Raíz se queda con todo, y no recuerda el pacto."],
                  ["legajo", "Y la Crónica de esta era queda en gris. Mis archivos también. Todo lo que copié."]], back: "a" },
      q2: { say: [["legajo", "La verdad. Quién hizo qué en el invierno. Quién vendió, quién compró. Los nombres verdaderos de la Corte también. Ninguna sombra va a poder esconderse."],
                  ["noctambula", "Y la Corte se dispersa. Por segunda vez. Mis sombras van a vivir en las orillas de otros pueblos, con el nombre dicho, sin tierra."]], back: "a" },
      q3: { say: [["gualda", "Vive escondida. No puede decir su nombre nunca. Si lo dice, dice el verso, y el verso se suelta. Sus hijos lo heredan. Y los hijos de sus hijos."],
                  ["gualda", "Yo sé lo que es un nombre que se escapa. Ella va a saber lo que es uno que no puede salir. No sé cuál es peor."]], back: "a" },
      velo: { say: [[null, "No haces nada. La sombra sube. Cubre el Corazón, baja por los caminos, entra en el Prado, en las Cuevas, en el Fondo. Es suave. Huele a tierra mojada."],
                    [null, "A la mañana, la gente se despierta tranquila. Los vecinos se saludan. Nadie sabe por qué estaba enojado. Nadie sabe quién murió en el invierno."],
                    ["legajo", "Mis rollos están en blanco. Todos. Los miro y no sé qué decían."],
                    ["noctambula", "Paz. Ya está. Y en el Corazón, las estatuas ya no son de nadie."]], end: { xp: 60, flag: "m6_velo" } },
      nombres: { say: [[null, "Empiezas tú. Dices los nombres que sabes, los del Libro, los de los pozos, los de los muertos de la pared. Legajo lee los de sus archivos. Gualda dice el suyo, otra vez, más fuerte."],
                       [null, "La gente se acerca. Cada uno dice uno. Los de la Corte también, los verdaderos, temblando. La sombra se detiene. Con cada nombre, baja un poco."],
                       [null, "Al amanecer, la sombra volvió a la grieta. Todos saben todo. Nadie puede esconderse."],
                       ["noctambula", "La Corte se dispersa hoy. Por segunda vez. Mis sombras se van con los nombres dichos, a vivir donde las dejen. Usted lo eligió. Que lo recuerde. Ahora todo se recuerda."]], end: { xp: 60, flag: "m6_nombres" } },
      guardado: { say: [[null, "Llegan los nueve. El Barrio con su mesa, las Casas con su libro, el Fuego con las tablillas rotas, el Bosque con los oídos abiertos, los Altos con el cuaderno de versos, la Corte, las Mareas con los chicos mojados, la Hondura con su punzón, el Fondo con sus soñadores."],
                        [null, "Legajo trae a una niña de sombra, chica, seria. Le lee el verso al oído. La niña lo repite sin voz. Desde ahora, ese es su nombre verdadero."],
                        [null, "Los nueve juran protegerla sin saber cómo se llama. La niña se va con una familia de las Mareas, lejos. La sombra vuelve a la grieta, despacio, como si alguien la hubiera calmado."],
                        ["gualda", "Ya está. Guardado. Yo voy a decir mi nombre a todos, para que nadie le pregunte el suyo. Ese es mi trabajo ahora."]], end: { xp: 60, flag: "m6_guardado" } },
    } },
  });

  /* ==================== Entrega 2: el Prado, el Cráter y el Bosque ==================== */

  /* ---------- Prado Aurora: el tío de las Casas, la escuela, la cola, los nombres usados, la mesa, el juicio, el farol y la nana ---------- */
  add("aurora", {
    "e6-tio": { kind: "encuentro", need: { era: 6, layer: 1 }, who: { lumbre: "Lumbre, de las Casas del Farol", tojo: "Tojo, de las Casas del Farol" }, start: "a", nodes: {
      a: { say: [[null, "En la sala del Concejo del Prado hay una silla vacía con un farol tallado en el respaldo. Un hombre mayor, de abrigo largo y bastón con punta de plata, la acaricia con la mano enguantada."],
                 ["lumbre", "Lumbre, de las Casas del Farol. Esta silla fue de mi familia trescientos años. Nos la quitaron después del invierno, cuando se supo lo de la leña. Ahora nadie se acuerda de lo de la leña. Pagamos para eso."],
                 ["lumbre", "Mañana pido la silla de vuelta. Las Casas saben gobernar. El Barrio sabe quejarse. Alguien tiene que mandar, y mejor quien sabe."]],
           opts: [{ t: "«Tojo escribió la historia de las Casas. Está todo ahí.»", go: "libro", cNeed: "e6_historiaCasas" },
                  { t: "«¿Usted se acuerda de lo de la leña?»", go: "acuerda", once: true },
                  { t: "Contarle al Concejo lo de la leña antes de la votación", go: "contar" },
                  { t: "«Pida la silla. Pero que el Barrio tenga otra al lado.»", go: "trato" },
                  { t: "No meterte", go: "nada" }] },
      libro: { say: [["lumbre", "Tojo. Mi sobrino. Escribió un libro y me dejó sin silla antes de pedirla. El chico tiene la nariz de su abuelo y la boca de su madre: las dos cosas me molestan."],
                     ["tojo", "Tío, la leña está en el libro. No la puse yo. La pusieron ellos. Yo solo dejé de taparla."]], back: "a" },
      acuerda: { say: [["lumbre", "No. Fui al pozo como todos. Pero sé que hubo algo, porque lo pagué. Uno no paga por olvidar algo bueno."],
                       ["lumbre", "Eso no cambia que las Casas sepan gobernar. Lo que hicimos en el invierno lo hicimos para sobrevivir. Ustedes hicieron lo mismo. Nosotros lo hicimos mejor."]], back: "a" },
      contar: { say: [[null, "La noche antes de la votación vas casa por casa. Cuentas lo que dice la pared de las Cuevas: las Casas guardaron leña mientras el Barrio quemaba sillas."],
                      [null, "Al día siguiente, el Concejo vota. Lumbre pierde por tres votos. Sale de la sala sin bastón: se le olvidó en la silla."],
                      ["lumbre", "Usted les devolvió el odio. Ahora tienen motivo. ¿Eso es mejor? Mañana el Barrio va a pedir mi casa. Y va a tener razón, y va a ser peor."]], end: { xp: 16, flag: "e6_tioDenunciado" } },
      trato: { say: [["lumbre", "¿Una silla para el Barrio? ¿Al lado de la mía?"],
                     [null, "Lo piensa. Mira la silla vacía. Mira la puerta, por donde se oye el ruido del Barrio en la calle."],
                     ["lumbre", "Bueno. Dos sillas. La mía más alta. No discuta: es lo más que le saco a un viejo que no se acuerda de qué hizo."]], end: { xp: 14, flag: "e6_tioTrato" } },
      nada: { say: [[null, "Al día siguiente, Lumbre recupera la silla. Nadie vota en contra: nadie recuerda por qué habría que votar en contra."],
                    [null, "Esa tarde, el Concejo sube el precio del pan del Barrio. Lumbre dice que es para pagar la leña del próximo invierno."]], end: { xp: 8, flag: "e6_tioConcejo" } },
    } },

    "e6-escuela": { kind: "encuentro", need: { era: 6, layer: 1 }, who: { mimbre: "Mimbre, maestra del Prado" }, start: "a", nodes: {
      a: { say: [[null, "En una escuela chica del Prado, veinte chicos sentados en el suelo copian en pizarras. Una mujer joven con el pelo atado con un lápiz camina entre ellos."],
                 ["mimbre", "Mimbre, maestra. Les estoy enseñando la historia del Claro. La de la Crónica, la que manda el Concejo. Hay un problema: me preguntan por qué el Barrio y las Casas no se hablan. Y la Crónica no dice nada del invierno."],
                 ["mimbre", "Un chico me preguntó si el invierno existió. Le dije que sí. Me preguntó cómo sabía. No supe qué decirle. Yo también fui al pozo."]],
           opts: [{ t: "«La Crónica culpó a la Corte. ¿Eso también lo enseña?»", go: "corte", cNeed: "m3_culpaCorte" },
                  { t: "Traer a los chicos a leer la pared de las Cuevas", go: "pared" },
                  { t: "«Enséñeles que no se sabe. Que eso también es historia.»", go: "nosabe" },
                  { t: "«Enseñe la Crónica. Es lo que hay.»", go: "cronica" }] },
      corte: { say: [["mimbre", "Sí. Que la Corte despertó la Raíz, hace tres generaciones. Los chicos de sombra se sientan al fondo. Nadie les dijo que se sienten al fondo. Se sientan solos."],
                     ["mimbre", "Lo que más me asusta es eso: que no hace falta decir nada. Lo aprenden igual."]], back: "a" },
      pared: { say: [[null, "Bajas con veinte chicos a las Cuevas. La Hondura les deja leer las paredes, con una lámpara cada tres. Leen nombres, fechas, «la verde escondió leña»."],
                     [null, "Un chico del Barrio encuentra el nombre de su bisabuela. Una chica de las Casas encuentra el de su familia, al lado de una lista de leña. Se miran."],
                     ["mimbre", "Hoy aprendieron más que en un año. Y van a volver a casa a preguntar. Los padres no me lo van a perdonar. Ojalá."]], end: { xp: 18, flag: "e6_escuelaPared" } },
      nosabe: { say: [[null, "Mimbre escribe en la pizarra grande: «Hubo un invierno. No sabemos todo lo que pasó. Algunos pagaron para olvidarlo»."],
                      [null, "Los chicos la copian. Uno levanta la mano y pregunta por qué alguien pagaría para olvidar. Mimbre tarda en contestar."],
                      ["mimbre", "Le dije la verdad: porque dolía. Me preguntó si a mí me dolía. Le dije que no sé. Esa es la clase más honesta que di."]], end: { xp: 14, flag: "e6_escuelaNoSabe" } },
      cronica: { say: [[null, "Mimbre sigue con la Crónica. Los chicos copian fechas, reyes, victorias. Ninguna pregunta más."],
                       ["mimbre", "Así es más fácil. Mañana es igual. Y pasado. Y dentro de veinte años, ellos van a enseñar lo mismo, sin saber qué falta."]], end: { xp: 8, flag: "e6_escuelaCronica" } },
    } },

    "e6-cola": { kind: "encuentro", need: { era: 6, layer: 2 }, who: {}, start: "a", nodes: {
      a: { say: [[null, "La cola de los pozos empieza en el Prado, en la plaza, antes del amanecer. Al final de todo, sentada en el suelo, hay una niña de unos diez años con una moneda apretada en la mano."],
                 [null, "Le preguntas qué hace ahí. Dice que su mamá se murió hace un mes, de fiebre, y que ella no para de llorar. Que en el pozo le van a sacar el llanto."],
                 [null, "«Si me olvido de mamá, ya no lloro. Mi tía dice que es lo mejor. Ella se olvidó de mi tío y ahora se ríe»."]],
           opts: [{ t: "Acompañarla hasta el pozo", go: "pozo" },
                  { t: "Quedarte con ella en la plaza, sin ir a ningún lado", go: "quedarse" },
                  { t: "Llevarla al Fondo, con la soñadora", go: "sopor", cNeed: "e6_suenosContados" },
                  { t: "Llevarla a lo de Desmemoria, que tiene una regla", go: "regla", cNeed: "e6_colaAtendida" }] },
      pozo: { say: [[null, "La acompañas todo el camino. Tarda casi un día. Al llegar, Desmemoria la mira mucho rato, y después le cobra."],
                    [null, "Sube del pozo con la cara seca. Te pregunta quién eres. Le dices que la acompañaste. Te da las gracias y se va corriendo hacia su tía."],
                    [null, "Esa noche, en su casa, alguien quema un vestido de mujer que nadie sabe de quién era."]], end: { xp: 8, flag: "e6_ninaOlvida" } },
      quedarse: { say: [[null, "Te sientas con ella. No dices nada. La cola avanza. Ella llora. Después deja de llorar y te cuenta de su mamá: que cantaba mal, que hacía sopa de zapallo, que se reía con la boca abierta."],
                        [null, "Al mediodía, la cola ya pasó. Ella mira la moneda."],
                        [null, "«Mañana vengo otra vez». No vuelve. Al mes la ves en la plaza, jugando. Todavía llora a veces. Se acuerda de la sopa."]], end: { xp: 18, flag: "e6_ninaRecuerda" } },
      sopor: { say: [[null, "La llevas al Fondo. Sopor la recibe en la sala de los soñadores y le cuenta que a veces sueña con mamás que no conoce."],
                     [null, "«Si la olvidas, yo la voy a soñar. Alguien va a llorar por ella igual. ¿Prefieres que sea yo, o tú?»"],
                     [null, "La niña lo piensa con la seriedad de los diez años. Dice que prefiere ella. Que es su mamá."]], end: { xp: 16, flag: "e6_ninaRecuerda" } },
      regla: { say: [[null, "La llevas directo al pozo del medio. Desmemoria la escucha. Después le devuelve la moneda."],
                     [null, "«Tú sabes qué quieres olvidar. Pero no sabes qué se va con eso. Vuelve cuando seas grande. Si todavía quieres, te atiendo yo»."],
                     [null, "La niña se va enojada. Desmemoria te mira y se encoge de hombros. Rompió la regla de la Corte por la suya."]], end: { xp: 16, flag: "e6_ninaDevuelta" } },
    } },

    "e6-yesquero": { kind: "encuentro", need: { era: 6, layer: 2 }, who: { yesquero: "Yesquero, comerciante del Prado", gualda: "Gualda, la Nombrada" }, start: "a", nodes: {
      a: { say: [[null, "En una tienda del Prado, un hombre gordo y amable cuenta monedas detrás del mostrador. Detrás de él, barriendo, hay una sombra flaca que no levanta la vista."],
                 ["yesquero", "Yesquero, comerciante. Esa es mi ayudante. Le sé el nombre verdadero. Lo dijo un borracho en la plaza. Con el nombre, le pido que se olvide de lo que le debo cada fin de mes. Lo olvida. Es la ley de la sombra, no la mía."],
                 [null, "Más allá, en la puerta, Gualda escucha con los puños apretados."],
                 ["gualda", "Gualda de la Tercera Cortina, hija de Umbrío. Así nos tratan afuera. Por eso nos callamos los nombres mil años. No era capricho."]],
           opts: [{ t: "«¿Cuántas sombras le trabajan así?»", go: "cuantas", once: true },
                  { t: "Contarlo en la plaza: que todos sepan lo que hace", go: "plaza" },
                  { t: "Pagarle a la ayudante lo que le debe, delante de él", go: "pagar", fx: { cost: 15 } },
                  { t: "Pedirle a Gualda que le enseñe a la ayudante a elegir un nombre nuevo", go: "nombre" }] },
      cuantas: { say: [["yesquero", "Tres. Bueno, cuatro. Los nombres se consiguen. Una sombra borracha, una pelea, un chico que no sabe. Se venden en la Hondonada, en voz baja."],
                       ["yesquero", "No les pego. No les grito. Les pago la comida. Solo me olvido de pagarles lo demás. Y ellas se olvidan de pedirlo. Es limpio."]], back: "a" },
      plaza: { say: [[null, "Lo cuentas en la plaza a gritos. La gente se junta. Algunos se ríen. Otros miran a Yesquero con asco."],
                     [null, "Esa semana, la tienda pierde la mitad de los clientes. Las cuatro sombras se van. Yesquero contrata a otras cuatro, más baratas, de otro pueblo."],
                     ["gualda", "Lo vieron todos. Sirve. Un poco. Ahora el que use un nombre lo va a hacer más callado. Eso también es algo."]], end: { xp: 14, flag: "e6_yesqueroExpuesto" } },
      pagar: { say: [[null, "Cuentas las monedas sobre el mostrador, una por una, delante de Yesquero. La ayudante te mira sin entender. Después las agarra con las dos manos."],
                     ["yesquero", "Muy bien. Le pagó usted. La próxima vez le pido que se olvide de esto también. Así es la sombra."],
                     ["gualda", "No. Porque se lo voy a recordar yo, todos los meses. Una sombra con el nombre dicho no olvida si otra le recuerda. Eso él no lo sabe."]], end: { xp: 16, flag: "e6_ayudantePagada" } },
      nombre: { say: [[null, "Gualda se lleva a la ayudante a la parte de atrás. Hablan en voz baja mucho rato. Cuando vuelven, la ayudante tiene la cara distinta."],
                      ["gualda", "Ya tiene otro. Nuevo. El viejo no le sirve más a él. Ya no le funciona. Mañana le va a pedir que se olvide, y ella le va a pedir el sueldo."],
                      ["yesquero", "¿Se puede hacer eso? Nadie me dijo que se podía hacer eso."]], end: { xp: 18, flag: "e6_nombreNuevoAyudante" } },
    } },

    "e6-mesalarga": { kind: "encuentro", need: { era: 6, layer: 2 }, who: { rastrojo: "Rastrojo, del Barrio" }, start: "a", nodes: {
      a: { say: [[null, "En la calle del Barrio hay una mesa larga, de puerta a puerta, hecha con tablones de cercas viejas. Hoy comen treinta familias. Hay sopa, pan, y alguien trajo una guitarra con dos cuerdas."],
                 ["rastrojo", "Rastrojo. Esto empezó con dos sillas. Ahora todo el Barrio come aquí los domingos. Nadie se acuerda de por qué se odiaba. Comemos igual."],
                 ["rastrojo", "El problema es ese. En la punta de la calle hay gente de las Casas mirando. Quieren sentarse. Y la mitad del Barrio dice que no, aunque no se acuerdan por qué."]],
           opts: [{ t: "«Antes no se hablaban y comieron igual. Esto empezó así.»", go: "empezo", cNeed: "e6_mesaJunta" },
                  { t: "Invitar a los de las Casas a la mesa", go: "invitar" },
                  { t: "«La mesa es del Barrio. Que las Casas hagan la suya.»", go: "barrio" },
                  { t: "Dejar una silla vacía en la punta, para quien quiera", go: "silla" }] },
      empezo: { say: [["rastrojo", "Ya sé. La vecina de la verde y yo. Ella me pasó la sal. Lo cuento cada domingo. Es la historia del Barrio ahora, más que el invierno."],
                      ["rastrojo", "Pero una cosa es la vecina. Otra cosa son las Casas. A las Casas les tenemos un odio que no es de nadie, es de todos. Ese es más difícil."]], back: "a" },
      invitar: { say: [[null, "Vas hasta la punta de la calle y traes a tres de las Casas. Los sientas en el medio. Nadie les pasa nada. Pasa un rato largo."],
                       [null, "Una vieja del Barrio les sirve sopa, sin mirarlos. Después les pasa el pan. Al final de la tarde, uno de las Casas toca la guitarra de dos cuerdas, mal."],
                       ["rastrojo", "La vieja que les sirvió es la que vio a Tojo con la llave. Le pregunté por qué les dio sopa. Dijo que la sopa no se acuerda de nada."]], end: { xp: 18, flag: "e6_mesaCasas" } },
      barrio: { say: [["rastrojo", "La suya. Sí. Que hagan la suya."],
                      [null, "A la semana, las Casas arman su mesa en la calle de al lado, con mantel blanco. Las dos mesas se ven desde la esquina. Nadie cruza."],
                      ["rastrojo", "Dos mesas. Antes había dos casas. Crecimos. El odio también."]], end: { xp: 10, flag: "e6_dosMesas" } },
      silla: { say: [[null, "Pones una silla al final de la mesa, con un plato vacío. Nadie dice nada."],
                     [null, "Pasan tres domingos. Al cuarto, un chico de las Casas se sienta. Come sin hablar y se va. Al quinto, vuelve con su hermana."],
                     ["rastrojo", "Ni los invitamos ni los echamos. Vinieron. Así es más lento. A lo mejor dura más."]], end: { xp: 16, flag: "e6_sillaVacia" } },
    } },

    "e6-juicio": { kind: "dialogo", need: { era: 6, layer: 3 }, who: { rastrojo: "Rastrojo, del Barrio", mimbre: "Mimbre, maestra del Prado" }, start: "a", nodes: {
      a: { say: [[null, "En la plaza del Prado hay otro juicio. Un hombre robó la caja del Concejo. Lo vieron. Al día siguiente fue al pozo. Ahora jura que no se acuerda."],
                 ["mimbre", "Es el tercero este mes. Roban, van al pozo, vuelven limpios. Los chicos de mi escuela ya lo saben. Uno me preguntó si podía pegarle a su hermano si después iba al pozo."],
                 ["rastrojo", "Hay que decidir qué hace el Prado con esto. Una vez y para siempre. Si no, cada uno decide a su modo, y el modo es el pozo."]],
           opts: [{ t: "«Con Tojo se castigó el acto. Que sea igual.»", go: "acto", cNeed: "m6_castigoActo" },
                  { t: "«Con Tojo se perdonó a la persona. Ahora se paga eso.»", go: "persona", cNeed: "m6_perdonPersona" },
                  { t: "«Que vaya a la Hondura y lea lo que hizo.»", go: "hondura", cNeed: "m6_recuerdoForzado" },
                  { t: "«Que el que vaya al pozo antes de un juicio pague el doble.»", go: "doble" },
                  { t: "«Que se cierre la cola del pozo para los acusados.»", go: "cerrar" }] },
      acto: { say: [["rastrojo", "Igual que con Tojo. Lo hizo. Paga. Se acuerde o no. Así quedó la ley."],
                    [null, "Lo condenan a devolver la caja con su trabajo. Acepta. Llora. No sabe por qué."],
                    ["mimbre", "Por lo menos los chicos aprenden algo claro: el pozo no limpia. Me alcanza."]], end: { xp: 14, flag: "e6_leyActo" } },
      persona: { say: [["rastrojo", "Perdonamos a Tojo porque ya no era el que cerró la puerta. Ahora este dice lo mismo. Y el próximo. Usted abrió esa puerta. Ahora mire quién entra."],
                       [null, "Lo perdonan. Se va a su casa. Esa noche, alguien le rompe las ventanas. La ley no castigó. La calle, sí."],
                       ["mimbre", "Si el Concejo no castiga, castiga la calle. Y la calle no va al pozo. La calle se acuerda."]], end: { xp: 10, flag: "e6_leyCalle" } },
      hondura: { say: [[null, "Lo llevan a las Cuevas. Le leen lo que hizo, grabado esa misma mañana por un picador que lo vio. El hombre escucha callado."],
                       ["rastrojo", "No se acuerda. Pero lo sabe. Ahora cada juicio del Prado termina en la pared. Así quedó: el que olvida, lee."],
                       ["mimbre", "Le voy a enseñar eso a los chicos. Que la memoria se puede prestar."]], end: { xp: 18, flag: "e6_leyPared" } },
      doble: { say: [["rastrojo", "¿El doble? Bueno. Que el pozo sea caro para el que tiene algo que tapar."],
                     [null, "La ley sale ese día. A la semana, los ladrones dejan de ir al pozo antes del juicio. Van después. El Concejo no pensó en eso."],
                     ["mimbre", "Siempre hay un después. Las leyes del Prado siempre se olvidan del después."]], end: { xp: 12, flag: "e6_leyDoble" } },
      cerrar: { say: [[null, "El Concejo manda una carta a la reina Noctámbula: que no atienda a acusados. La reina contesta con dos palabras: «¿Cómo sé?»"],
                      ["rastrojo", "Tiene razón. No tienen cara de acusados. Tienen cara de gente. La cola sigue igual."]], end: { xp: 8, flag: "e6_leyCola" } },
    } },

    "e6-farol": { kind: "encuentro", need: { era: 6, layer: 3 }, who: { tojo: "Tojo, de las Casas del Farol" }, start: "a", nodes: {
      a: { say: [[null, "En lo alto de la casa de las Casas del Farol hay un farol de vidrio verde, el más viejo del Prado. Tojo lo limpia con un trapo. Abajo, en el patio, hay un montón de libros atados."],
                 ["tojo", "La Crónica Oficial. Las copias de las Casas. Mi tío quiere mandarlas al pozo de la Hondonada. Dice que si la sombra puede borrar recuerdos, también puede borrar libros. Que así nadie lee más quién tuvo la culpa hace tres generaciones."],
                 ["tojo", "Yo escribí un libro con la verdad. Él quiere borrar el que tiene la mentira. Los dos borramos algo. No sé quién está peor."]],
           opts: [{ t: "«La Crónica culpó a las Casas. ¿Por eso la quiere borrar?»", go: "casas", cNeed: "m3_culpaCasas" },
                  { t: "«La Crónica culpó a la Corte. Las Casas salieron limpias.»", go: "corte", cNeed: "m3_culpaCorte" },
                  { t: "«Guarde los dos libros. El falso y el verdadero.»", go: "dos" },
                  { t: "«Que los borre. Una mentira menos.»", go: "borrar" },
                  { t: "«Llévelos a la Hondura. Que los graben con una nota.»", go: "nota" }] },
      casas: { say: [["tojo", "Sí. Las Casas cargaron la culpa del Espejo, de la Raíz, de todo. Mi tío dice que eso nos hizo débiles. Que por eso en el invierno guardamos leña: porque nadie nos iba a dar nada."],
                     ["tojo", "No sé si es verdad. Pero es lo que él cree. Y lo cree tanto que quiere borrar libros."]], back: "a" },
      corte: { say: [["tojo", "Sí. Por eso mi tío la quiere borrar, aunque nos favorece. Dice que mientras exista, la Corte la va a discutir. Que es mejor que no haya nada que discutir."],
                     ["tojo", "Mi tío le tiene más miedo a una discusión que a una mentira. Así son las Casas."]], back: "a" },
      dos: { say: [[null, "Tojo sube los libros atados a la torre del farol. Los acomoda en un estante, al lado del suyo. Tres libros: la Crónica, su historia, y uno en blanco."],
                   ["tojo", "El falso, el verdadero, y uno para lo que venga. Que el que suba a limpiar el farol los lea todos. Mi tío no sube nunca. Le dan miedo las escaleras."]], end: { xp: 18, flag: "e6_librosGuardados" } },
      borrar: { say: [[null, "Los libros bajan a la Hondonada en un carro. Desmemoria los mira sin entender: nunca le trajeron libros. Los tira al pozo uno por uno."],
                      [null, "Al día siguiente, en todas las escuelas del Prado, las páginas de la Crónica que hablaban de la culpa están en blanco. Nadie sabe cómo. Los chicos no lo notan."],
                      ["tojo", "Una mentira menos. Y un hueco más. No sé qué va a crecer en el hueco."]], end: { xp: 10, flag: "e6_cronicaBorrada" } },
      nota: { say: [[null, "La Hondura graba la Crónica entera en una pared, con una nota al principio, en letra grande: «Esto es lo que se dijo. No es lo que pasó. Lo que pasó está en la pared de enfrente»."],
                    ["tojo", "Así cualquiera puede comparar. Mi tío va a decir que es peor. Yo digo que es la primera vez que las Casas aparecen en la pared por algo que no hicieron mal."]], end: { xp: 16, flag: "e6_cronicaGrabada" } },
    } },

    "e6-nana": { kind: "encuentro", need: { era: 6, layer: 3 }, who: { rastrojo: "Rastrojo, del Barrio" }, start: "a", nodes: {
      a: { say: [[null, "En el patio de Rastrojo, una vieja de ochenta años canta algo bajito mientras pela papas. Los chicos del Barrio la escuchan sin saber qué es."],
                 ["rastrojo", "Mi abuela. Es la nana. La de la Estrella. Los chicos no la saben. Sus padres la olvidaron en el pozo junto con el invierno, porque la cantaban en las filas del Fondo."],
                 ["rastrojo", "Mi abuela es la última del Barrio que la sabe entera. Cuando se muera, se termina. Ella dice que no le importa. Que una nana no sirve para nada."]],
           opts: [{ t: "«¿Por qué dice que no sirve?»", go: "sirve", once: true },
                  { t: "Aprenderla con ella y enseñarla a los chicos", go: "aprender" },
                  { t: "Llevar a la abuela a las Cuevas a que la graben", go: "grabar" },
                  { t: "«Si no la quiere enseñar, es suya.»", go: "suya" }] },
      sirve: { say: [[null, "La vieja deja de cantar y te mira."],
                     [null, "«La canté en la fila del Fondo todo el invierno. Mis hijos se murieron igual. Una nana no da de comer. Que la olviden. Mejor»."]], back: "a" },
      aprender: { say: [[null, "Vas todas las tardes a pelar papas con la abuela. Al principio no te canta. A la semana, sí. Te corrige cada nota."],
                        [null, "Un domingo la cantas en la mesa larga, delante de todos. Los chicos se ríen de tu voz. Después la repiten. Al rato, la canta media calle."],
                        [null, "La abuela no dice nada. Pero esa noche, desde la ventana, se la oye cantar la última estrofa, la que tú no sabías."]], end: { xp: 20, flag: "e6_nanaBarrio" } },
      grabar: { say: [[null, "La llevas a las Cuevas en una carreta. Canta delante de una pared lisa. Mica graba la letra, y debajo, con rayas, cómo sube y baja la voz."],
                      [null, "La abuela mira la pared con los ojos mojados."],
                      [null, "«Ahí quedó. Ya no es mía. Ahora es de la piedra». Se va sin despedirse. No vuelve a cantarla nunca."]], end: { xp: 14, flag: "e6_nanaGrabada" } },
      suya: { say: [["rastrojo", "Suya. Sí. Tiene derecho."],
                    [null, "La abuela sigue pelando papas. Ya no canta. Los chicos se aburren y se van a jugar."]], end: { xp: 8, flag: "e6_nanaPerdida" } },
    } },
  });

  /* ---------- Cráter Tibio: la maestra del Gremio, lo fiado, el aprendiz, el pozo chico, las manos, la huelga, los clavos y la cuenta ---------- */
  add("crater", {
    "e6-crisol": { kind: "dialogo", need: { era: 6, layer: 1 }, who: { crisol: "Crisol, maestra del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "En la oficina del Gremio, sobre la Forja grande, una mujer de hombros anchos y delantal de cuero revisa tablillas con una lupa. Tiene una mano gris hasta la muñeca."],
                 ["crisol", "Crisol, maestra del Gremio. Usted viene por lo de las deudas. Todos vienen por lo de las deudas. Le explico: el Gremio fió carbón en el invierno para que el Cráter no se muriera. Ese carbón lo pagamos nosotros. Alguien tiene que devolverlo."],
                 ["crisol", "Si cada obrero que va al pozo deja de deber, el Gremio quiebra. Si el Gremio quiebra, el próximo invierno no hay quien fíe. Es así de simple. Lo que no es simple es que me odien por eso."]],
           opts: [{ t: "«Las tablillas del invierno se rompieron en la plaza.»", go: "rotas", cNeed: "e6_tablillasRotas" },
                  { t: "«¿Usted fue al pozo?»", go: "pozo", once: true },
                  { t: "«Que el Gremio cobre en trabajo, no en monedas.»", go: "trabajo" },
                  { t: "«Perdone las deudas del invierno. Todas.»", go: "perdonar" },
                  { t: "«Cobre. Tiene razón.»", go: "cobrar" }] },
      rotas: { say: [["crisol", "Se rompieron. Lo vi. Aplaudieron. Esa noche hice la cuenta: el Gremio perdió cuarenta inviernos de carbón. Me quedé sin dormir."],
                     ["crisol", "No le guardo rencor. Le guardo la cuenta. Que es peor, porque la cuenta no se olvida en ningún pozo."]], back: "a" },
      pozo: { say: [["crisol", "No. La maestra no olvida. Me acuerdo de cada obrero que se murió de frío porque no le fié. Fueron pocos. Me acuerdo de los nombres."],
                    ["crisol", "Ellos se olvidaron de que les fié. Yo me acuerdo de los que no. Así está repartida la memoria en el Cráter."]], back: "a" },
      trabajo: { say: [["crisol", "En trabajo. Una hora de forja por cada saco. Sin intereses. Es lento. Es justo."],
                       [null, "Lo escribe en una tablilla nueva y la cuelga en la puerta de la Forja. A la semana, los obreros hacen fila para trabajar la deuda. Algunos se quejan. La mayoría no."],
                       ["crisol", "Lo que no se recuerda se puede pagar con lo que sí se sabe hacer. Me gusta. No se lo diga a nadie: dicen que soy dura."]], end: { xp: 18, flag: "e6_deudaTrabajo" } },
      perdonar: { say: [["crisol", "¿Todas? ¿Y el próximo invierno?"],
                        [null, "La convences a medias. Perdona las de los que tienen hijos chicos. Las demás, no."],
                        ["crisol", "La mitad. Es lo que puedo. La otra mitad la cargo yo. Si el invierno vuelve, me van a pedir fiado los mismos que hoy me aplauden."]], end: { xp: 14, flag: "e6_deudaMitad" } },
      cobrar: { say: [["crisol", "Tengo razón. Gracias. Casi nadie me la da."],
                      [null, "Esa tarde, Recaudo sale con las tablillas. Vuelve de noche, con la bolsa llena y la cara gris."],
                      ["crisol", "Ahí está lo fiado. Devuelto. Nadie se va a acordar de por qué debía. Todos se van a acordar de quién cobró."]], end: { xp: 8, flag: "e6_deudaCobradaTodo" } },
    } },

    "e6-fiado": { kind: "encuentro", need: { era: 6, layer: 1 }, who: { recaudo: "Recaudo, cobrador del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "En un rincón de la Forja, Recaudo come pan duro sentado sobre un saco de carbón. Tiene dos tablillas en las rodillas: una grande, con el sello del Gremio, y una chica, sin sello, gastada."],
                 ["recaudo", "Recaudo. Esta grande es lo que el Gremio me mandó anotar. Esta chica es mía. Son los que fié sin anotar en la grande. Los que no podían pagar nunca. Los anoté para acordarme de que los perdoné."],
                 ["recaudo", "Si la maestra la ve, me echa. Si la quemo, nadie sabe que alguien los ayudó. Ni ellos. Todos fueron al pozo."]],
           opts: [{ t: "«¿Por qué los anotó, si los perdonó?»", go: "porque", once: true },
                  { t: "«Muéstresela a la maestra.»", go: "mostrar" },
                  { t: "«Muéstresela a ellos. Que sepan.»", go: "ellos" },
                  { t: "«Quémela. Lo bueno no necesita testigos.»", go: "quemar" }] },
      porque: { say: [["recaudo", "Porque si no lo anoto, no pasó. En el Cráter todo se anota. Hasta lo que uno regala."],
                      ["recaudo", "Y porque algún día alguien me va a decir que fui un cobrador sin alma. Quiero tener algo para mostrarle. A mí, por lo menos."]], back: "a" },
      mostrar: { say: [[null, "Recaudo sube a la oficina con la tablilla chica. Tarda una hora. Cuando baja, tiene la cara roja."],
                       ["recaudo", "La leyó entera. No me echó. Me dijo que eran cuarenta sacos. Que el Gremio los perdió por mi culpa. Después me dijo que ella habría hecho lo mismo, pero anotado en la grande."],
                       ["recaudo", "Ahora la chica está colgada al lado de la grande, en la puerta. Dice: «Perdonado». Con el sello."]], end: { xp: 18, flag: "e6_fiadoSellado" } },
      ellos: { say: [[null, "Recaudo lee la tablilla chica en la plaza del Cráter, nombre por nombre. La gente escucha. Algunos no saben de qué habla."],
                     [null, "Una mujer se acerca, llorando. Dice que no se acordaba, que pensó que el Gremio nunca la ayudó. Que odió a Recaudo diez años."],
                     ["recaudo", "Ahora me odia menos. O me odia distinto. No sé. Me dio un pan. El primer pan que me dan en el Cráter."]], end: { xp: 16, flag: "e6_fiadoLeido" } },
      quemar: { say: [[null, "Recaudo tira la tablilla chica al fuego de la Forja. La madera arde rápido. Él mira las llamas sin decir nada."],
                      ["recaudo", "Ya está. Nadie sabe. Yo tampoco, pronto. Para eso no necesito pozo: con el tiempo alcanza."]], end: { xp: 10, flag: "e6_fiadoQuemado" } },
    } },

    "e6-aprendiz": { kind: "encuentro", need: { era: 6, layer: 2 }, who: { crisol: "Crisol, maestra del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "En la Forja hay un muchacho de veinte años sentado frente al yunque, con el martillo en la mano, sin moverse. Mira el hierro rojo como si no supiera qué es."],
                 ["crisol", "Fue el mejor aprendiz que tuve. En el invierno forjó día y noche para la leña de todos. Se le murió el padre en la Forja, de frío, durmiendo al lado del fuego apagado. Fue al pozo a olvidar eso."],
                 ["crisol", "Se olvidó del padre. Y del oficio. El padre le enseñó todo. El pozo no corta fino. Ahora no sabe ni agarrar el martillo."]],
           opts: [{ t: "«¿Se puede volver a aprender?»", go: "volver", once: true },
                  { t: "Enseñarle de nuevo con Crisol, desde el principio", go: "ensenar" },
                  { t: "Contarle de su padre, aunque duela", go: "padre" },
                  { t: "«Que haga otro oficio. Uno que no le duela.»", go: "otro" }] },
      volver: { say: [["crisol", "Se puede. Lo hacen las Mareas con el agua, dicen. Pero se aprende distinto. Antes tenía las manos del padre. Ahora va a tener las suyas."],
                      ["crisol", "No sé si eso es peor. Las del padre se le habrían gastado igual."]], back: "a" },
      ensenar: { say: [[null, "Durante un mes vas a la Forja cada mañana. Crisol le enseña como a un chico: cómo se agarra, cómo se mira el color del hierro, cómo se respira al golpear."],
                       [null, "Al mes, forja un clavo torcido. Lo mira mucho rato. Dice que le parece conocido, el gesto, no el clavo."],
                       ["crisol", "Las manos se acuerdan de lo que la cabeza olvidó. Un poco. Ese clavo es suyo y es de su padre. No se lo digo. Ya lo va a saber."]], end: { xp: 18, flag: "e6_aprendizForja" } },
      padre: { say: [[null, "Le cuentas lo que te dijo Crisol: el padre, el invierno, el fuego apagado. El muchacho escucha con el martillo en la mano."],
                     [null, "No llora. No se acuerda. Pero deja el martillo en el yunque, despacio, como quien deja algo prestado."],
                     ["crisol", "No volvió a la Forja. Se fue al Bosque a cortar leña. Dice que no quiere aprender algo que alguien tuvo que morirse para enseñarle. No lo entiendo. Lo respeto."]], end: { xp: 14, flag: "e6_aprendizSabe" } },
      otro: { say: [["crisol", "Otro oficio. Bueno. Lo mando a las cuentas. Sabe sumar."],
                    [null, "Al año, el muchacho es el que anota las deudas del Gremio. Lo hace bien. Nunca se acerca al yunque. Cuando pasa por la Forja, se tapa los oídos."]], end: { xp: 8, flag: "e6_aprendizCuentas" } },
    } },

    "e6-pozochico": { kind: "encuentro", need: { era: 6, layer: 2 }, who: { recaudo: "Recaudo, cobrador del Gremio", crisol: "Crisol, maestra del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "Detrás de la Forja, en una cueva chica, alguien cavó un pozo. Adentro hay sombra, poca, traída en baldes desde la Hondonada. Hay una cola de obreros. Cobra un muchacho del Gremio."],
                 ["recaudo", "El pozo chico. El Gremio lo puso hace un mes. Más barato que la Hondonada. Los obreros olvidan aquí lo que les duele y vuelven al trabajo el mismo día. Rinde más."],
                 ["recaudo", "La maestra no sabe. O hace que no sabe. Lo pusieron los de arriba. La sombra en balde se cansa rápido: a veces se lleva de más."]],
           opts: [{ t: "«¿Qué es llevarse de más?»", go: "demas", once: true },
                  { t: "Tapar el pozo chico con piedras", go: "tapar" },
                  { t: "Avisarle a la reina Noctámbula que le roban sombra", go: "reina" },
                  { t: "Decirle a la maestra Crisol", go: "maestra" }] },
      demas: { say: [["recaudo", "Un obrero vino a olvidar una pelea con su mujer. Se olvidó de la mujer. Volvió a la casa y no la conocía. Ella está con su madre ahora."],
                     ["recaudo", "En la Hondonada eso no pasa tanto. Allá la sombra es honda y sabe. Aquí es de balde. Tonta."]], back: "a" },
      tapar: { say: [[null, "De noche, con Recaudo, llenas el pozo chico de piedras. Tardan hasta el amanecer. La sombra se queja, como agua que no puede salir."],
                     [null, "A la mañana, el muchacho del Gremio encuentra el pozo tapado. Grita. Nadie sabe quién fue. Recaudo silba mientras cobra."],
                     ["recaudo", "Lo van a volver a cavar. En otro lado. Pero hoy nadie se olvidó de su mujer."]], end: { xp: 16, flag: "e6_pozoChicoTapado" } },
      reina: { say: [[null, "Le mandas un mensaje a la Corte. Al día siguiente bajan cuatro sombras con velo al Cráter. Se llevan la sombra en baldes, de vuelta a la Hondonada, sin decir una palabra."],
                     ["recaudo", "La reina no quiere competencia. Bien. Ahora la sombra es solo de ella. Eso tampoco me gusta. Pero por lo menos es honda."]], end: { xp: 12, flag: "e6_pozoChicoReina" } },
      maestra: { say: [[null, "Crisol baja a la cueva con un martillo de forja. Mira la cola, mira el pozo, mira al muchacho que cobra."],
                       [null, "No dice nada. Rompe el borde del pozo a martillazos hasta que la sombra se escurre por la grieta y se va."],
                       ["crisol", "En mi Forja se olvida trabajando, no comprando. Que se enteren los de arriba. Que vengan a decírmelo a la cara."]], end: { xp: 18, flag: "e6_pozoChicoRoto" } },
    } },

    "e6-manosgrises": { kind: "encuentro", need: { era: 6, layer: 2 }, who: {}, start: "a", nodes: {
      a: { say: [[null, "En el banco de la plaza del Cráter, un viejo con las dos manos grises hasta los codos mira la Forja. Te sientas a su lado. Te pregunta cómo se llama."],
                 [null, "Le dices que no sabes. Te dice que él tampoco. Fue al pozo a olvidar el dolor de las manos, que le dolían cada noche desde las Forjas Hondas. Se olvidó del dolor. Y de su nombre."],
                 [null, "«Las manos me duelen igual. El nombre no vuelve. Mal negocio»."]],
           opts: [{ t: "Buscar su nombre en la pared de las Cuevas", go: "buscar" },
                  { t: "«Elija uno nuevo.»", go: "nuevo" },
                  { t: "Preguntarle a los obreros viejos si lo conocen", go: "obreros" }] },
      buscar: { say: [[null, "Bajas a las Cuevas con él. Mica busca entre las paredes de las Forjas Hondas. Encuentra una lista de obreros con manos grises. Hay cuarenta nombres."],
                      [null, "Le lees los cuarenta. En el número veintitrés, el viejo levanta la cabeza. «Ese». No sabe por qué. Lo sabe."],
                      [null, "Se va repitiéndolo en voz baja, como quien aprende una palabra nueva en otro idioma."]], end: { xp: 18, flag: "e6_nombreHallado" } },
      nuevo: { say: [[null, "Lo piensa. Mira la Forja, el humo, el yunque."],
                     [null, "«Yunque. Me llamo Yunque. Es lo que más miré en la vida». Se ríe con la boca sin dientes."],
                     [null, "Al mes, todo el Cráter le dice Yunque. Él contesta. Dice que el nombre viejo, si vuelve, que vuelva. Que tiene otro por si acaso."]], end: { xp: 14, flag: "e6_nombreNuevoViejo" } },
      obreros: { say: [[null, "Preguntas por toda la Forja. Nadie lo conoce. Todos fueron al pozo a olvidar el invierno, y él está pegado al invierno."],
                       [null, "Una vieja, al final, dice que le parece que se llamaba como un árbol. No sabe cuál."],
                       [null, "El viejo se queda con eso. Dice que le alcanza. Que un árbol es un buen nombre aunque no se sepa cuál."]], end: { xp: 10, flag: "e6_nombreArbol" } },
    } },

    "e6-huelga": { kind: "dialogo", need: { era: 6, layer: 3 }, who: { crisol: "Crisol, maestra del Gremio", recaudo: "Recaudo, cobrador del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "La Forja grande está fría. Los obreros están sentados en la plaza, con los brazos cruzados. No trabajan. Han pintado en la pared del Gremio: «No debemos lo que no recordamos»."],
                 ["crisol", "Huelga. Tres días. Sin Forja no hay herramientas para el Bosque ni clavos para los Altos. Los de arriba me piden que llame a la guardia. No quiero."],
                 ["recaudo", "Los obreros piden que se borren las deudas que no recuerdan. Los de arriba piden que se cobren. Y yo soy el que tiene que ir a decirles a unos lo que dicen los otros."]],
           opts: [{ t: "«Que paguen con trabajo, como dijo la maestra.»", go: "trabajo", cNeed: "e6_deudaTrabajo" },
                  { t: "«Que lean la tablilla de lo perdonado. Que sepan que hubo ayuda.»", go: "fiado", cNeed: "e6_fiadoSellado" },
                  { t: "Sentarte con los obreros en la plaza", go: "sentarse" },
                  { t: "«Que traigan a la guardia. La Forja no puede parar.»", go: "guardia" },
                  { t: "«Que cada obrero diga en voz alta lo que debe y lo que recuerda.»", go: "decir" }] },
      trabajo: { say: [["crisol", "Ya está en la puerta. Lo escribí. Los de arriba lo borraron anoche. Lo vuelvo a escribir hoy."],
                       [null, "Crisol sube a la Forja con tiza y lo escribe en letras grandes, delante de todos. Los obreros miran. Uno se levanta. Después otro."],
                       ["recaudo", "Se termina la huelga. Los de arriba van a echar a la maestra. Ella lo sabe. Escribió igual."]], end: { xp: 18, flag: "e6_huelgaTrabajo" } },
      fiado: { say: [["recaudo", "La tablilla chica. Sí. La leo otra vez, en la plaza."],
                     [null, "Recaudo lee los cuarenta nombres. Algunos obreros se miran. Uno dice: «A mí me fiaron y no lo sabía». Otro: «A mi madre»."],
                     ["crisol", "No se terminó la huelga. Pero se acabaron los gritos. Ahora están hablando. Eso es más difícil de parar que una huelga, y mejor."]], end: { xp: 16, flag: "e6_huelgaHabla" } },
      sentarse: { say: [[null, "Te sientas en la plaza con los obreros. Te dan un pedazo de pan. No te preguntan nada. Pasan dos días."],
                        [null, "Al tercero, Crisol baja de la oficina y se sienta también. Los de arriba la miran desde la ventana."],
                        ["crisol", "Si la maestra se sienta, la Forja no es de los de arriba. Es de los que la hacen andar. Mañana trabajamos. Sin deudas del invierno. Y que me echen."]], end: { xp: 20, flag: "e6_huelgaGana" } },
      guardia: { say: [[null, "La guardia del Gremio llega con palos. Los obreros se levantan despacio. Nadie pelea. Vuelven a la Forja con la cabeza gacha."],
                       ["crisol", "Ganamos. La Forja anda. Y cada obrero se va a acordar de esto, aunque se olvide de la deuda. Esa memoria no la saca ningún pozo."]], end: { xp: 8, flag: "e6_huelgaRota" } },
      decir: { say: [[null, "Uno por uno, los obreros dicen en voz alta lo que deben y lo que recuerdan. La mayoría no recuerda nada. Algunos sí: un saco, una noche, un hijo enfermo."],
                     ["recaudo", "Los que recuerdan pagan. Los que no, no. Es raro. Es justo de una manera que nunca vi."],
                     ["crisol", "Lo raro es que los que recuerdan quieren pagar. Dicen que es lo único que les quedó de esa noche."]], end: { xp: 16, flag: "e6_huelgaRecuerdo" } },
    } },

    "e6-clavos": { kind: "encuentro", need: { era: 6, layer: 3 }, who: { crisol: "Crisol, maestra del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "En la pared de la Forja hay un clavo torcido colgado de un hilo, con una tablilla debajo. La tablilla está en blanco: alguien raspó lo que decía."],
                 ["crisol", "Ese clavo lo hizo una forjadora de la ladera sur, hace dos generaciones. Dicen que forjaba en frío, que no quería quemarse las manos. Nadie se acuerda de su nombre. Lo rasparon en el invierno para usar la madera de leña."],
                 ["crisol", "Los aprendices le tocan el clavo antes de trabajar. Para la suerte. No saben de quién es. Yo tampoco."]],
           opts: [{ t: "«Se llamaba Chispa. Lo dice el Libro.»", go: "chispa", cNeed: "end_e5chispa_A" },
                  { t: "«Era Chispa. Forjaba con las manos grises.»", go: "chispaB", cNeed: "end_e5chispa_B" },
                  { t: "Buscar el nombre en las Cuevas", go: "buscar" },
                  { t: "«Déjelo sin nombre. Es de todos.»", go: "todos" }] },
      chispa: { say: [["crisol", "¿Chispa? ¿La que dirigía el Cráter desde una silla, con las dos manos grises, sin cobrar el calor?"],
                      [null, "Escribe el nombre en la tablilla con un carbón. Los aprendices se acercan a mirar."],
                      ["crisol", "Ahora tiene nombre. Y los aprendices van a preguntar quién era, y alguien va a tener que contar. Así se empieza a recordar: con una pregunta."]], end: { xp: 18, flag: "e6_clavoChispa" } },
      chispaB: { say: [["crisol", "Chispa. La que enterró un martillo debajo de la Forja. Hay un lugar en el suelo donde a los viejos les tiemblan las manos al pasar. Nunca supe por qué."],
                       [null, "Escribe el nombre. Después baja la vista al suelo, al lugar del martillo, y lo pisa con cuidado."]], end: { xp: 16, flag: "e6_clavoChispa" } },
      buscar: { say: [[null, "En las Cuevas, Mica encuentra el nombre en una pared de las Forjas Hondas: una niña de la ladera sur que forjaba clavos torcidos. Chispa."],
                      [null, "Vuelves con el nombre. Crisol lo escribe en la tablilla."],
                      ["crisol", "La piedra se acordaba. Nosotros no. A veces pienso que la Hondura nos va a sobrevivir a todos, y que lo único que va a quedar del Cráter es lo que ellos copiaron."]], end: { xp: 16, flag: "e6_clavoChispa" } },
      todos: { say: [["crisol", "De todos. Sí. Un clavo sin dueño que todos tocan."],
                     [null, "La tablilla sigue en blanco. Un aprendiz nuevo toca el clavo y dice que es de un gigante que comía piedras. Otro dice que es de una reina. Se ríen."]], end: { xp: 8, flag: "e6_clavoSinNombre" } },
    } },

    "e6-cuenta": { kind: "dialogo", need: { era: 6, layer: 3 }, who: { crisol: "Crisol, maestra del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "Crisol te llama a la oficina de noche. Sobre la mesa hay una tablilla vieja, de hielo de raíz, que no se derrite. Tiene el sello del Fondo Blanco."],
                 ["crisol", "El Gremio también debe. En el invierno, el Fondo nos fió hielo para guardar la comida de los obreros. Esta es la deuda. Nadie la cobró nunca. El Fondo la tiene anotada igual."],
                 ["crisol", "Le exijo a cada obrero que pague lo que olvidó. Y el Gremio debe algo que nadie recuerda más que el Fondo. Si lo pago, el Gremio quiebra. Si no lo pago, soy una hipócrita."]],
           opts: [{ t: "«Después del Deshielo, el Fondo no tiene nada. Págueles.»", go: "deshielo", cNeed: "m5_deshielo" },
                  { t: "«Págueles en trabajo, como a los obreros.»", go: "trabajo" },
                  { t: "«Llévela al pozo de la Hondonada.»", go: "pozo" },
                  { t: "«Cuéntelo en la plaza. Que los obreros sepan que el Gremio también debe.»", go: "plaza" }] },
      deshielo: { say: [["crisol", "Sin hielo, sin comida, sin poder. Y una tablilla de hielo de raíz que no se derrite. Lo único del Fondo que quedó entero es la deuda."],
                        [null, "Crisol manda al Fondo cien herramientas, gratis, en tres carros. No pide nada."],
                        ["crisol", "No es la deuda. Es otra cosa. Pero el Fondo la va a recibir como si fuera. Así se paga lo que ya no se puede pagar."]], end: { xp: 18, flag: "e6_gremioPagaFondo" } },
      trabajo: { say: [["crisol", "En trabajo. Sí. La Forja le hace al Fondo un portón nuevo, de hierro, para el granero. Un mes de trabajo de todos."],
                       [null, "Los obreros trabajan el portón sin quejarse. Dicen que si la maestra paga, ellos también."],
                       ["crisol", "Ya está. Ahora soy dura, pero no hipócrita. Me gusta más."]], end: { xp: 16, flag: "e6_gremioPagaFondo" } },
      pozo: { say: [[null, "Crisol baja la tablilla a la Hondonada. Desmemoria la mira con curiosidad: es la primera vez que le traen una deuda en vez de una persona."],
                    [null, "La tablilla cae al pozo. No se derrite. Flota en la sombra, entera, sin hundirse."],
                    ["crisol", "El hielo de raíz no se olvida. Hasta el pozo lo sabe. Me la llevo de vuelta. La cuelgo en la oficina. Que me mire."]], end: { xp: 12, flag: "e6_gremioDebe" } },
      plaza: { say: [[null, "Crisol lee la deuda del Gremio en la plaza, delante de los obreros. Se hace un silencio largo."],
                     [null, "Un obrero se ríe. Después otro. Al final se ríe toda la plaza. Crisol se ríe también, sin ganas, y después con ganas."],
                     ["crisol", "Todos debemos. Hasta el Gremio. Ahora nos miramos distinto. Igual hay que pagar. Pero ya no estoy arriba de nadie."]], end: { xp: 18, flag: "e6_gremioConfiesa" } },
    } },
  });

  /* ---------- Bosque Hondo: el vendedor de musgo, el roble que repite, las hojas, el Concejo, los robles huecos, la Raíz que habla y las semillas ---------- */
  add("forest", {
    "e6-helecho": { kind: "encuentro", need: { era: 6, layer: 1 }, who: { helecho: "Helecho, vendedor de musgo" }, start: "a", nodes: {
      a: { say: [[null, "A la entrada del Bosque, un muchacho flaco con un carro lleno de musgo verde llama a la gente que pasa. Tiene los dos oídos tapados con musgo, y habla muy fuerte."],
                 ["helecho", "¡Helecho! ¡Musgo para el Silencio! ¡Para no oír al Bosque, para olvidar sin pagar al pozo! ¡Una moneda la bolsa!"],
                 ["helecho", "Mi hermana Acebo dice que lo que hago está mal. Que el Bosque tiene que oírse. Pero ella también se lo pone. Yo por lo menos lo cobro."]],
           opts: [{ t: "«¿Por qué no quiere oír el Bosque?»", go: "porque", once: true },
                  { t: "Sacarle el musgo de un oído, con cuidado", go: "sacar" },
                  { t: "«Venda musgo para dormir, no para olvidar.»", go: "dormir" },
                  { t: "Comprar una bolsa", go: "comprar", fx: { cost: 1 } }] },
      porque: { say: [["helecho", "¿Qué?"],
                      [null, "Repites la pregunta, más fuerte."],
                      ["helecho", "¡Porque se oye a los muertos! ¡El Bosque repite! Mi padre se murió en un roble hueco, en el invierno. A veces el roble dice su nombre. ¡No quiero oírlo!"]], back: "a" },
      sacar: { say: [[null, "Le sacas el musgo de un oído. El muchacho se queda quieto. El Bosque cruje. Lejos, muy lejos, se oye una voz que dice un nombre."],
                     [null, "Helecho se pone pálido. Escucha. Después se pone el musgo otra vez, rápido."],
                     ["helecho", "Lo dijo. Lo oí. Era la voz de él. ¿Por qué hizo eso? ¿Por qué...? Gracias. No sé. Gracias."]], end: { xp: 16, flag: "e6_helechoOye" } },
      dormir: { say: [["helecho", "¿Para dormir? ¿Hay quien quiera solo dormir?"],
                      [null, "Al día siguiente, el carro tiene un cartel nuevo: «Musgo para dormir. No para el Silencio». Vende la mitad. Pero a la noche, la gente del Bosque duerme sin pesadillas y se despierta con los oídos libres."],
                      ["helecho", "Gano menos. Mi hermana me habla otra vez. Es raro cómo se paga lo bueno."]], end: { xp: 14, flag: "e6_musgoDormir" } },
      comprar: { say: [[null, "Le pagas una moneda. Te da una bolsa de musgo húmedo, verde, que huele a tierra."],
                       ["helecho", "¡Gracias! Para el Silencio del sábado. ¡Que no oiga nada!"]], end: { xp: 6, flag: "e6_musgoComprado" } },
    } },

    "e6-robleeco": { kind: "encuentro", need: { era: 6, layer: 1 }, who: { acebo: "Acebo, del Concejo del Musgo" }, start: "a", nodes: {
      a: { say: [[null, "En el medio del Bosque hay un roble enorme, viejo, con la corteza gris. Tiene un hueco en el tronco, del tamaño de una puerta. Del hueco sale un murmullo."],
                 ["acebo", "Acebo. Es el roble de la puerta tallada. En el invierno vivió una familia adentro. Ahora repite cosas. Voces, pedazos de canciones, nombres. Nadie quiere pasar cerca."],
                 ["acebo", "El Concejo quiere cortarlo. Dicen que está enfermo. Yo creo que está hablando. No sé de qué."]],
           opts: [{ t: "«Si es el roble de la puerta, ¿qué pasó con la familia?»", go: "familia", once: true },
                  { t: "Meterte en el hueco y escuchar", go: "escuchar" },
                  { t: "Convencer al Concejo de no cortarlo", go: "salvar" },
                  { t: "«Que lo corten. Un árbol que habla no deja dormir.»", go: "cortar" }] },
      familia: { say: [["acebo", "Vivieron. Casi todos. Se fueron en primavera. Uno, el abuelo, se quedó adentro, dormido. No se despertó."],
                       ["acebo", "Los nietos fueron al pozo. Se olvidaron del abuelo. El roble no. El roble lo tiene adentro, de alguna manera."]], back: "a" },
      escuchar: { say: [[null, "Te metes en el hueco. Adentro huele a madera y a humo viejo. El murmullo se hace claro: es un viejo contando un cuento a unos chicos. Un cuento sobre una cantora y una Raíz."],
                        [null, "El viejo se equivoca, se ríe, vuelve a empezar. Los chicos le piden que siga."],
                        ["acebo", "¿Qué oyó? ¿Qué decía? Lo veo en su cara. Es algo bueno. ¿No? Es algo bueno."]], end: { xp: 18, flag: "e6_robleOido" } },
      salvar: { say: [[null, "Hablas en el Concejo. Llevas a los nietos del abuelo al roble. Les pides que escuchen."],
                      [null, "Al principio no oyen nada. Después, uno reconoce la risa. No sabe de quién es. Pero dice que la conoce."],
                      ["acebo", "El Concejo no lo corta. Le pusieron un banco al lado. Los nietos vienen los domingos. No se acuerdan del abuelo. Escuchan igual."]], end: { xp: 16, flag: "e6_robleSalvado" } },
      cortar: { say: [[null, "Al día siguiente, los leñadores cortan el roble. Tarda toda la mañana. Cuando cae, el murmullo se corta de golpe."],
                      ["acebo", "Ya no habla. Tenía cuatrocientos años. Hacía cuarenta que repetía al viejo. Ahora no lo repite nadie."]], end: { xp: 8, flag: "e6_robleCortado" } },
    } },

    "e6-hojas": { kind: "encuentro", need: { era: 6, layer: 2 }, who: { acebo: "Acebo, del Concejo del Musgo" }, start: "a", nodes: {
      a: { say: [[null, "En una cabaña del Concejo hay montones de hojas secas, cada una con algo escrito con carbón. Son las hojas del Silencio con los oídos abiertos: lo que la gente oye en el Bosque, anotado."],
                 ["acebo", "Las hojas. Las juntamos desde que se abrió el Silencio. Ya hay mil. Algunas dicen tonterías. Otras dicen nombres. Y hay una que me da miedo."],
                 [null, "Te alcanza una hoja. Dice, con letra torcida: «La que cierra la puerta del granero se llama como la niebla»."]],
           opts: [{ t: "«¿Quién la escribió?»", go: "quien", once: true },
                  { t: "Llevar las hojas a la Hondura para que las graben", go: "hondura", cNeed: "e6_silencioAbierto" },
                  { t: "Quemar la hoja que da miedo", go: "quemar" },
                  { t: "Leer las hojas en voz alta en el Concejo", go: "leer" }] },
      quien: { say: [["acebo", "Un chico de doce años. No sabe qué quiere decir. Dice que el Bosque lo dijo con voz de mujer enojada."],
                     ["acebo", "Yo creo que es del invierno. Alguien que cerró el granero. Alguien con nombre de niebla. Hay muchos nombres de niebla en el Fondo."]], back: "a" },
      hondura: { say: [[null, "Llevas las mil hojas a las Cuevas en dos sacos. Mica las lee todas. Graba las que tienen nombres, una por una."],
                       ["acebo", "Ahora el Bosque tiene su pared. Lo que dice la Raíz por los árboles queda en la piedra. Lo que dice cuando duerme."],
                       [null, "En la pared nueva, entre muchas, queda grabada la de la niebla. Mica la marca con una raya: «Sin confirmar»."]], end: { xp: 18, flag: "e6_hojasGrabadas" } },
      quemar: { say: [[null, "Acebo quema la hoja en la estufa. Se arruga, se pone negra, se deshace."],
                      ["acebo", "Una sola. Las otras novecientas noventa y nueve se quedan. No sé por qué esa me dio miedo. Será que se parecía a algo verdadero."]], end: { xp: 10, flag: "e6_hojaQuemada" } },
      leer: { say: [[null, "En el Concejo, Acebo lee las hojas en voz alta. Una hora. Dos. La gente escucha. Algunos lloran con un nombre. Otros se ríen con una tontería."],
                    [null, "Cuando lee la de la niebla, una vieja del fondo se levanta y se va. Nadie la sigue."],
                    ["acebo", "Esa vieja era del Fondo. Vino al Bosque después del invierno. No sé cómo se llama. Ahora quiero saber. Y no quiero."]], end: { xp: 14, flag: "e6_hojasLeidas" } },
    } },

    "e6-concejobosque": { kind: "dialogo", need: { era: 6, layer: 2 }, who: { acebo: "Acebo, del Concejo del Musgo", helecho: "Helecho, vendedor de musgo" }, start: "a", nodes: {
      a: { say: [[null, "El Concejo del Musgo se reúne bajo los robles. Hoy se vota una cosa: si la Corte puede abrir un pozo de sombra en el Bosque. La reina mandó una carta con sello de humo."],
                 ["acebo", "La reina ofrece un pozo chico, cerca del claro. Gratis para el Bosque el primer año. A cambio, el Bosque le vende madera sin preguntar para qué."],
                 ["helecho", "¡Yo voto que no! ¡Si hay pozo, nadie me compra musgo! Bueno, también voto que no porque está mal. Las dos cosas."]],
           opts: [{ t: "«El Bosque escucha. Un pozo es para no escuchar.»", go: "no" },
                  { t: "«Que abran el pozo, pero que el Concejo decida quién entra.»", go: "control" },
                  { t: "«Si la gente quiere olvidar, que pueda. Que voten que sí.»", go: "si" }] },
      no: { say: [[null, "El Concejo vota. Gana el no por cuatro votos. Acebo escribe la respuesta a la reina en una hoja seca."],
                  ["acebo", "«El Bosque prefiere oír lo que le duele». Así le puse. Va a pensar que somos tontos. A lo mejor lo somos."],
                  ["helecho", "Bien. Bien. Mañana vendo musgo. ¿Qué? No me miren así."]], end: { xp: 16, flag: "e6_bosqueSinPozo" } },
      control: { say: [[null, "El Concejo vota que sí, con una condición: el pozo lo atiende alguien del Bosque, y nadie entra sin que el Concejo lo sepa."],
                       ["acebo", "Un pozo con portero. Es menos malo. O es lo mismo con más papeles. No sé."],
                       [null, "La reina acepta. Manda la sombra en carros cerrados. El portero es un viejo del Concejo que nunca dice que no."]], end: { xp: 12, flag: "e6_bosquePozoPortero" } },
      si: { say: [[null, "Gana el sí. La reina manda la sombra al día siguiente. En una semana, el Silencio con los oídos abiertos se queda vacío."],
                  ["acebo", "Todos al pozo. Ya nadie escucha. El Bosque habla solo."],
                  ["helecho", "Me quedé sin trabajo. Y sin hermana: ella no me habla porque yo voté que no y perdimos. No tiene sentido. Nada tiene sentido."]], end: { xp: 8, flag: "e6_bosquePozo" } },
    } },

    "e6-huecos": { kind: "encuentro", need: { era: 6, layer: 2 }, who: { tilo: "Tilo, el más viejo del Bosque" }, start: "a", nodes: {
      a: { say: [[null, "En un roble hueco hay una puerta tallada, vieja, con musgo en las bisagras. Adentro, sentado en una silla de mimbre, un viejo enorme fuma una pipa de corteza."],
                 ["tilo", "Tilo. Soy el más viejo del Bosque. Viví en este roble todo el invierno, con veinte personas más. De chico. Me acuerdo de todo. No fui al pozo. No quise."],
                 ["tilo", "Los otros diecinueve se olvidaron. Algunos se murieron. Los que viven me saludan en la calle y no saben que dormimos juntos en este tronco, codo con codo, tres años. Yo sí sé."]],
           opts: [{ t: "«¿Por qué no fue al pozo?»", go: "porque", once: true },
                  { t: "Juntar a los que vivieron en el roble, aunque no se acuerden", go: "juntar" },
                  { t: "Pedirle que cuente la historia en el Concejo", go: "contar" },
                  { t: "Dejarlo con su pipa", go: "dejar" }] },
      porque: { say: [["tilo", "Porque fue lo mejor de mi vida. Raro, ¿no? Hambre, frío, veinte en un tronco. Y fue lo mejor. Nunca más estuve tan cerca de nadie."],
                      ["tilo", "Los otros se olvidaron del frío. Y de mí. Yo me quedé con los dos."]], back: "a" },
      juntar: { say: [[null, "Tardas una semana en encontrarlos. Son once. Los llevas al roble un domingo. Entran, se sientan, se miran sin saber por qué están ahí."],
                      [null, "Tilo les cuenta. El invierno, la puerta, la sopa compartida, el chico que nació adentro. Nadie se acuerda. Una mujer llora igual."],
                      ["tilo", "No se acuerdan. Pero vinieron. Y se quedaron a comer. Once en un tronco otra vez. Con eso me puedo morir tranquilo. No ahora. Más adelante."]], end: { xp: 20, flag: "e6_robleJuntos" } },
      contar: { say: [[null, "Tilo habla en el Concejo, con la pipa apagada. Cuenta el invierno como fue: lo bueno y lo malo, la sopa y los muertos."],
                      [null, "Los jóvenes escuchan como si fuera un cuento viejo. Los que estuvieron ahí escuchan como si fuera de otro."],
                      ["tilo", "Les gustó. Dicen que cuento bien. Nadie me creyó del todo. Pero ahora es una historia del Bosque. Eso dura más que yo."]], end: { xp: 16, flag: "e6_tiloCuenta" } },
      dejar: { say: [[null, "Te sientas un rato con él. Fuma. No habla más. Afuera, los robles crujen con el viento."],
                     ["tilo", "Gracias por no pedirme nada. Todos me piden que cuente. Usted no. Eso también es escuchar."]], end: { xp: 10, flag: "e6_tiloSolo" } },
    } },

    "e6-raizbosque": { kind: "dialogo", need: { era: 6, layer: 3 }, who: { acebo: "Acebo, del Concejo del Musgo" }, start: "a", nodes: {
      a: { say: [[null, "Es de noche. Acebo te lleva al claro más hondo del Bosque, donde las raíces de los robles salen de la tierra y se juntan. Ahí, en el suelo, la tierra está tibia."],
                 ["acebo", "Aquí la Raíz habla más fuerte. Ponga la oreja en el suelo. Pero antes, sáquese todo. El musgo, el miedo. Aquí se oye todo lo que el Claro olvidó."],
                 [null, "Pones la oreja en la tierra. Se oyen miles de voces. Todas al mismo tiempo. Lo que se vendió en los pozos, mezclado, como un mercado lejos."]],
           opts: [{ t: "Buscar una sola voz entre todas", go: "una" },
                  { t: "Hablarle a la Raíz, en voz baja", go: "hablar" },
                  { t: "Levantarte. Es demasiado.", go: "levantar" }] },
      una: { say: [[null, "Te concentras. Entre todas, una voz se acerca. Es una mujer que canta la nana, mal, riéndose. Alguien la olvidó de felicidad, como dijo la soñadora."],
                   [null, "La Raíz la repite. Despacio. Como si le gustara."],
                   ["acebo", "Le gusta. Mire. La tierra está más tibia ahí. Lo feliz también baja. Pocos lo olvidan, pero baja. Y la Raíz lo guarda mejor."]], end: { xp: 18, flag: "e6_raizFeliz" } },
      hablar: { say: [[null, "Le hablas a la tierra. Le dices que sabes lo que carga. Que lo que olvidan los pueblos lo carga ella. Que lo sientes."],
                      [null, "Las voces se callan. Todas a la vez. Un segundo. Dos. Después vuelven, igual que antes."],
                      ["acebo", "Se callaron. Por usted. Nadie le habló nunca así. Le cantan, le piden. Nadie le dice que lo siente."]], end: { xp: 20, flag: "e6_raizHablada" } },
      levantar: { say: [[null, "Te levantas. Te zumban los oídos. Por un rato no sabes dónde estás."],
                        ["acebo", "Está bien. A mí me pasó lo mismo la primera vez. Me puse el musgo un año entero después. Es mucho. Es todo lo que no queremos."]], end: { xp: 10, flag: "e6_raizDemasiado" } },
    } },

    "e6-semillas": { kind: "encuentro", need: { era: 6, layer: 3 }, who: { tilo: "Tilo, el más viejo del Bosque" }, start: "a", nodes: {
      a: { say: [[null, "Tilo te muestra una caja de madera, chica, llena de semillas de centeno. Son viejas, de antes del invierno. Las guardó todo este tiempo debajo de su cama."],
                 ["tilo", "Las guardó una mujer del Bosque, en el invierno. Avena se llamaba, creo. Las escondió del hambre para cuando terminara el frío. Se murió antes. Me las dejó a mí, de chico."],
                 ["tilo", "Nadie se acuerda de ella. Las semillas sí. Si las planto, crece el centeno de antes, el que nadie conoce. Si no las planto, se mueren conmigo."]],
           opts: [{ t: "«Avena las guardó. Lo dice el Libro.»", go: "avena", cNeed: "e5_semillasDentro" },
                  { t: "Plantarlas en el claro del Concejo", go: "plantar" },
                  { t: "Repartirlas entre los pueblos, un puñado cada uno", go: "repartir" },
                  { t: "«Guárdelas. Son lo último de ella.»", go: "guardar" }] },
      avena: { say: [["tilo", "¿Usted la conoció? ¿Cómo era? Yo era muy chico. Me acuerdo de las manos. No de la cara."],
                     [null, "Le cuentas lo que sabes. Tilo escucha con los ojos cerrados."],
                     ["tilo", "Entonces era terca. Me alegro. Las semillas tercas son las que crecen."]], back: "a" },
      plantar: { say: [[null, "Plantas las semillas con Tilo en el claro del Concejo. En primavera sale un centeno raro, alto, oscuro, que nadie vio nunca."],
                       [null, "Los chicos del Bosque lo llaman «el de la vieja». No saben qué vieja. Tilo no les dice."],
                       ["tilo", "Que no sepan. Que coman. Eso quería ella: que alguien comiera después. No que se acordaran."]], end: { xp: 18, flag: "e6_centenoViejo" } },
      repartir: { say: [[null, "Haces nueve bolsitas. Una por pueblo. Las llevas tú, de zona en zona, con una nota: «De una mujer del Bosque que guardó esto en el invierno»."],
                        [null, "Algunos pueblos las plantan. Otros las guardan. La Hondura graba la nota en una pared."],
                        ["tilo", "Nueve pueblos con un poco de ella. Ninguno sabe quién era. Pero todos tienen la misma semilla. Eso es algo."]], end: { xp: 16, flag: "e6_semillasNueve" } },
      guardar: { say: [["tilo", "Las guardo. Sí. Debajo de la cama. Cuando me muera, alguien las va a encontrar y no va a saber qué son."],
                       [null, "Cierra la caja. Pasa la mano por la tapa, despacio."]], end: { xp: 8, flag: "e6_semillasCaja" } },
    } },
  });

  /* ==================== Entrega 3: la Hondonada, el Lago y las Cuevas ==================== */

  /* ---------- Hondonada Umbría: el chambelán, el mercado de nombres, la madre de Desmemoria, el verso escondido o cantado, las cortinas, el pozo seco y la reina a solas ---------- */
  add("hollow", {
    "e6-humareda": { kind: "encuentro", need: { era: 6, layer: 1 }, who: { humareda: "Humareda, chambelán de la Corte" }, start: "a", nodes: {
      a: { say: [[null, "En un pasillo de la Corte, entre cortinas de humo, un hombre alto de túnica gris con bordados de plata te corta el paso. Sonríe con todos los dientes."],
                 ["humareda", "Humareda, chambelán de la Corte. Usted habla con la reina. Sé todo lo que pasa en estos pasillos. La reina es joven. Vende olvido como quien vende pan, sin pensar en lo que vale."],
                 ["humareda", "Yo pienso. Las Casas del Farol me pagan para que sus olvidos sean primero en la cola. El Gremio me paga para que los obreros olviden rápido. Con eso, la Corte compra lo que necesita. La reina no sabe. La reina no tiene que saber."]],
           opts: [{ t: "«¿Por qué me lo cuenta?»", go: "porque", once: true },
                  { t: "Contárselo a la reina", go: "reina" },
                  { t: "«Siga. Pero que la plata vaya a la cocina de la Corte.»", go: "cocina" },
                  { t: "«Cuénteselo usted a la reina. Mañana.»", go: "plazo" }] },
      porque: { say: [["humareda", "Porque usted va a enterarse igual. Mejor de mi boca, con mis razones, que de otra, sin ellas."],
                      ["humareda", "No soy malo. La Corte perdió su tierra una vez porque una reina fue honrada. Yo no voy a dejar que pase otra vez por otra reina honrada."]], back: "a" },
      reina: { say: [[null, "Se lo cuentas a Noctámbula esa misma noche. Ella escucha sin moverse, detrás del velo."],
                     [null, "En la mañana, Humareda ya no está en la Corte. Lo vieron salir hacia el Prado con un baúl y sin bordados."],
                     [null, "Una semana después, las Casas del Farol tienen un consejero nuevo. Alto, de túnica gris, con una sonrisa de todos los dientes."]], end: { xp: 16, flag: "e6_humaredaEchado" } },
      cocina: { say: [["humareda", "¿La cocina? ¿A la ayudante de cocina, la que dice su nombre a gritos?"],
                      [null, "Lo piensa. Asiente. Desde esa semana, la cocina de la Corte tiene pan blanco y carne dos veces por semana. Nadie sabe de dónde sale."],
                      ["humareda", "Bien. Ahora usted también es parte. Lo dulce de esto es que ya no puede contar nada sin contar lo suyo. Me gusta trabajar con gente así."]], end: { xp: 12, flag: "e6_humaredaCocina" } },
      plazo: { say: [["humareda", "¿Mañana? ¿Yo?"],
                     [null, "Al día siguiente, Humareda pide audiencia. Sale de la sala de la reina tres horas después, pálido, con los bordados arrancados."],
                     ["humareda", "Me quedo. Sin plata y sin bordados. La reina dice que un chambelán que confiesa vale más que uno honrado. No sé si es un premio o un castigo. Las dos cosas."]], end: { xp: 18, flag: "e6_humaredaConfiesa" } },
    } },

    "e6-mercadonombres": { kind: "encuentro", need: { era: 6, layer: 1 }, who: {}, start: "a", nodes: {
      a: { say: [[null, "En un rincón oscuro de la Hondonada, lejos de los pozos, un chico de sombra de unos catorce años vende papelitos doblados sobre una manta. Habla bajito."],
                 [null, "«Nombres. Verdaderos. De sombras de la Corte. Este es de una cocinera. Este de un guardia. Tres monedas cada uno. Con el nombre, la sombra olvida lo que usted le pida»."],
                 [null, "Te dice que los consigue en las tabernas, de borrachos que se pelean. Que su madre lo hacía antes que él. Que de algo hay que vivir."]],
           opts: [{ t: "Comprarle todos y quemarlos", go: "quemar", fx: { cost: 20 } },
                  { t: "Llevarlo con Gualda, que sabe lo que pesa un nombre", go: "gualda" },
                  { t: "Avisar a la guardia de la Corte", go: "guardia" },
                  { t: "Irte", go: "irte" }] },
      quemar: { say: [[null, "Le compras los treinta papelitos. El chico cuenta las monedas dos veces. Quemas los papeles en un brasero, uno por uno, sin leerlos."],
                      [null, "El chico mira el fuego. «Mañana consigo otros. Siempre hay borrachos». Se va silbando."],
                      [null, "Treinta sombras no saben que hoy les devolviste algo. Mañana el chico tiene treinta más."]], end: { xp: 12, flag: "e6_nombresQuemados" } },
      gualda: { say: [[null, "Llevas al chico a la cocina de la Corte, o adonde esté Gualda. Ella lo mira mucho rato."],
                      [null, "«Gualda de la Tercera Cortina, hija de Umbrío. Ese es el mío. Ya está. Ahora que lo sabes, véndelo. Te lo regalo»."],
                      [null, "El chico no sabe qué hacer con un nombre regalado. Se queda. Gualda le da sopa. Al mes, ayuda en la cocina. Ya no vende nombres. Dice que perdieron la gracia."]], end: { xp: 18, flag: "e6_chicoNombres" } },
      guardia: { say: [[null, "La guardia de la Corte llega al rato, con velos. Se llevan al chico y la manta. No dicen adónde."],
                       [null, "Al otro día, en el mismo rincón, hay otra manta. La atiende una mujer que dice ser la madre."]], end: { xp: 8, flag: "e6_chicoPreso" } },
      irte: { say: [[null, "Te vas. Detrás, el chico sigue hablando bajito con otro cliente."]], end: { xp: 4 } },
    } },

    "e6-madre": { kind: "dialogo", need: { era: 6, layer: 2 }, who: { desmemoria: "Desmemoria, del pozo" }, start: "a", nodes: {
      a: { say: [[null, "Desmemoria no está en el pozo. Lo encuentras sentado en la ladera de la Hondonada, con un dibujo en las manos: una cara de mujer, hecha con carbón, borrada y vuelta a hacer muchas veces."],
                 ["desmemoria", "Trato de dibujar a mi madre. Desde que la olvidé. Cada vez me sale distinta. Ninguna es ella. Ya no sé qué buscar."],
                 ["desmemoria", "Lo que se olvida baja a la Raíz. Eso dicen. Si alguien supiera bajar a buscarla... No. Nadie baja. El pozo no devuelve."]],
           opts: [{ t: "«La soñadora del Fondo sueña lo que otros olvidan.»", go: "sopor", cNeed: "e6_suenosContados" },
                  { t: "«Legajo copia la cara de quien va al pozo. Busquemos en el archivo.»", go: "archivo", cNeed: "e6_paginaLeida" },
                  { t: "«Su madre murió en la fila del Fondo. La Hondura graba las filas.»", go: "pared" },
                  { t: "«Deje de buscarla. Viva con el hueco.»", go: "hueco" }] },
      sopor: { say: [[null, "Lo llevas al Fondo. Sopor lo escucha. Esa noche duerme con el dibujo en el pecho."],
                     [null, "En la mañana, Sopor le describe una mujer: nariz larga, una cicatriz en la ceja, se reía tapándose la boca. Desmemoria llora con la cara entre las manos."],
                     ["desmemoria", "No me acuerdo. Pero es ella. Lo sé porque me dolió. Ahora tengo algo que dibujar. Es de otra, la cara. Pero es mía."]], end: { xp: 20, flag: "e6_madreSonada" } },
      archivo: { say: [[null, "Legajo busca en los rollos del último invierno, los de quién vino al pozo y con qué cara. No encuentra a la madre: ella no vino al pozo. Encuentra a Desmemoria, chico, con una nota."],
                       [null, "«Vino un chico de doce años. Dijo que quería olvidar a su madre. Traía en la mano una cinta de pelo azul. La dejó en el pozo»."],
                       ["desmemoria", "Una cinta azul. No me acuerdo. Pero esta noche voy a dibujarla con una cinta azul. Empiezo por ahí."]], end: { xp: 18, flag: "e6_madreCinta" } },
      pared: { say: [[null, "En las Cuevas, Mica busca las filas del Fondo, el último invierno. Encuentra una lista de muertos en la fila, grabada por un picador que hacía la cola."],
                     [null, "Uno de los nombres tiene al lado, chiquito: «madre del chico del pozo»."],
                     ["desmemoria", "Tiene nombre. Ni siquiera me acordaba de que tenía nombre. Lo voy a decir en voz alta cada noche antes de trabajar. Así algo de ella se queda arriba."]], end: { xp: 18, flag: "e6_madreNombre" } },
      hueco: { say: [["desmemoria", "Vivir con el hueco. Eso hago. Eso le vendo a la gente: un hueco limpio en lugar de un dolor sucio."],
                     [null, "Rompe el dibujo en pedazos chicos y los tira al pozo, desde arriba, sin respirar."],
                     ["desmemoria", "Ya está. Ni la cara inventada me queda. Mañana atiendo la cola como siempre."]], end: { xp: 8, flag: "e6_madreHueco" } },
    } },

    "e6-escondida": { kind: "dialogo", need: { era: 6, layer: 2, flag: "m6_versoNombre" }, who: { legajo: "Legajo, archivero del Velo" }, start: "a", nodes: {
      a: { say: [[null, "Legajo te espera en la galería de los archivos, con la puerta trancada. Está nervioso: se limpia los anteojos una y otra vez."],
                 ["legajo", "Alguien sabe. Anoche entraron a mi casa y revolvieron todo. Buscaban a mi nieta. Querían saber su nombre. Ya tiene siete años: ya lo sabe."],
                 ["legajo", "No sé quién fue. La reina, Humareda, alguien que quiere vender el verso en el pozo. Hay que sacarla de la Hondonada. ¿Pero adónde va una sombra chica que no puede decir su nombre?"]],
           opts: [{ t: "Llevarla a las Mareas, que viven de pueblo en pueblo", go: "mareas" },
                  { t: "Esconderla en las Cuevas, con la Hondura", go: "cuevas" },
                  { t: "«Quédese con ella. Nadie la conoce mejor que usted.»", go: "quedarse" }] },
      mareas: { say: [[null, "Esa noche sales de la Hondonada con la niña de la mano. Camina callada. No pregunta nada. Al amanecer llegan al Lago."],
                      [null, "Ondina la recibe sin preguntar. Le da otro nombre, uno de agua, de esos que se dicen en voz alta. La niña lo repite y sonríe por primera vez."],
                      ["legajo", "Las Mareas no se quedan en ningún lado. Ella tampoco. Es lo mejor. Es lo peor: no la voy a ver crecer."]], end: { xp: 18, flag: "e6_ninaMareas" } },
      cuevas: { say: [[null, "La bajas a las Cuevas. Mica la esconde en una galería vieja, de las que no tienen pared escrita. La niña aprende a picar piedra."],
                      ["legajo", "La Hondura no olvida y no vende. Si alguien sabe guardar algo, son ellos. Pero ahí abajo no hay sol."],
                      [null, "A la semana, la niña graba en una pared, con letra torcida, una sola palabra. Mica la tapa con barro antes de que alguien la lea."]], end: { xp: 16, flag: "e6_ninaCuevas" } },
      quedarse: { say: [["legajo", "Quedarme. Con mis rollos y mi nieta y mi puerta trancada."],
                        [null, "Legajo pone una tranca más. Deja de ir a los archivos de día. La niña juega en la galería, entre los estantes, sin salir nunca."],
                        ["legajo", "La voy a esconder entre papeles. Es lo único que sé hacer. Ojalá alcance."]], end: { xp: 10, flag: "e6_ninaArchivo" } },
    } },

    "e6-versotaberna": { kind: "encuentro", need: { era: 6, layer: 2, flag: "m6_versoTodos" }, who: { legajo: "Legajo, archivero del Velo" }, start: "a", nodes: {
      a: { say: [[null, "En la taberna más grande de la Hondonada se canta el noveno verso. Pero hay tres versiones. Tres grupos, en tres mesas, cada uno cantando la suya más fuerte que los otros."],
                 ["legajo", "Una dice que el pacto se paga con un canto. Otra, con una vida. La que yo leí dice que se paga con algo que se recuerda. Esa es la que menos se canta: no rima."],
                 ["legajo", "Lo di a todos para que nadie lo vendiera. Ahora no se vende. Se pelea. Anoche hubo una pelea con cuchillos por una palabra."]],
           opts: [{ t: "Cantar la versión verdadera en el medio de la taberna", go: "cantar" },
                  { t: "Llevar la versión verdadera a la Hondura para que la graben", go: "grabar" },
                  { t: "«Que canten las tres. Ya no es suyo.»", go: "tres" }] },
      cantar: { say: [[null, "Te subes a una mesa y cantas la que leyó Legajo. No rima. Suena mal. Las tres mesas se callan a mirarte."],
                      [null, "Alguien se ríe. Alguien te tira una jarra. Después, desde el fondo, una vieja la repite contigo, despacio."],
                      ["legajo", "Una persona. Una vieja la cantó con usted. Es poco. Es más que ayer."]], end: { xp: 16, flag: "e6_versoCantado" } },
      grabar: { say: [[null, "Mica graba la versión de Legajo en una pared nueva de las Cuevas, con la firma de Legajo al pie y la fecha."],
                      ["legajo", "Ahí está. La verdadera. Quien quiera comparar, que baje. La mayoría no va a bajar. Pero la piedra la va a tener cuando alguien la necesite."]], end: { xp: 16, flag: "e6_versoGrabado" } },
      tres: { say: [["legajo", "Ya no es mío. Sí."],
                    [null, "Las tres mesas siguen cantando. Al final de la noche se mezclan: una palabra de una, dos de otra. Nace una cuarta versión que nadie escribió."],
                    ["legajo", "Una cuarta. Así se hacen las leyendas. Así se pierden."]], end: { xp: 10, flag: "e6_versoMezclado" } },
    } },

    "e6-cortinas": { kind: "encuentro", need: { era: 6, layer: 2 }, who: { noctambula: "Reina Noctámbula" }, start: "a", nodes: {
      a: { say: [[null, "La reina te hace pasar por las siete cortinas de humo, despacio. En cada una se detiene. Cada cortina tiene un bordado distinto, casi borrado."],
                 ["noctambula", "Cada cortina es de una reina. Siete reinas desde el primer exilio. Cada una dejó un secreto bordado, que solo la siguiente sabe leer. Yo sé leer seis. La séptima es la mía, y está en blanco."],
                 ["noctambula", "Tengo que bordar algo antes de morir. Algo que la próxima tenga que guardar. No sé qué. Todo lo que sé ya lo vendí en el pozo o lo guardé en el secreto de la Raíz."]],
           opts: [{ t: "«¿Qué dicen las otras seis?»", go: "seis", once: true },
                  { t: "«Borde lo que hace el pozo. Que la próxima no lo venda.»", go: "pozo" },
                  { t: "«Déjela en blanco. Que la próxima no guarde nada.»", go: "blanco" },
                  { t: "«Borde su nombre verdadero.»", go: "nombre" }] },
      seis: { say: [["noctambula", "Una dice dónde está la primera tierra de la Corte. Otra, quién traicionó a Lóbrego. Otra, una receta de pan negro. Otra, un nombre de hombre, nada más."],
                    ["noctambula", "Ninguno sirve ya. Pero cada reina los leyó y los guardó. Así se hace una reina: cargando cosas que no sirven, por respeto."]], back: "a" },
      pozo: { say: [[null, "Noctámbula borda toda la noche. Al amanecer, en la séptima cortina hay un pozo redondo, y debajo, una raíz con muchas caras."],
                    ["noctambula", "La próxima reina va a saber lo que el pozo le cuesta a la Raíz. A lo mejor no vende. A lo mejor vende más caro. Por lo menos va a saber."]], end: { xp: 18, flag: "e6_cortinaPozo" } },
      blanco: { say: [["noctambula", "¿En blanco? ¿La primera reina sin secreto?"],
                      [null, "Lo piensa mucho. Al final no borda nada. La séptima cortina queda lisa, gris, con el humo pasando a través."],
                      ["noctambula", "Que la próxima vea una cortina en blanco y piense. Es lo más difícil que le puedo dejar."]], end: { xp: 16, flag: "e6_cortinaBlanca" } },
      nombre: { say: [["noctambula", "¿Mi nombre? Noctámbula es el de reina. El otro no lo sabe nadie. Ni usted."],
                      [null, "Te pide que te voltees. Oyes la aguja un rato largo. Cuando te vuelves, la séptima cortina tiene una palabra bordada en hilo negro sobre humo negro. No se lee."],
                      ["noctambula", "Ahí está. La próxima va a saber cómo me llamaba. Y va a poder hacerme olvidar, si quiere, aunque esté muerta. Así confían las reinas."]], end: { xp: 14, flag: "e6_cortinaNombre" } },
    } },

    "e6-pozoseco": { kind: "encuentro", need: { era: 6, layer: 3 }, who: { desmemoria: "Desmemoria, del pozo" }, start: "a", nodes: {
      a: { say: [[null, "El pozo del medio tiene la sombra más baja. Se ve el fondo: piedra húmeda, gris, llena de grietas. La cola espera igual, nerviosa."],
                 ["desmemoria", "Se está secando. Se vendió demasiado. Esta mañana una mujer se asomó y en vez de olvidar, se acordó. De algo que no era de ella. Gritó un nombre que nadie conocía."],
                 ["desmemoria", "Creo que la Raíz está llena. Ya no traga. Empieza a devolver. Pero devuelve mezclado."]],
           opts: [{ t: "«Cierre el pozo del medio. Hoy.»", go: "cerrar" },
                  { t: "Asomarte a escuchar lo que devuelve", go: "escuchar" },
                  { t: "«Mande la cola a los otros dos pozos.»", go: "otros" }] },
      cerrar: { say: [[null, "Desmemoria pone una tabla sobre el pozo y se sienta encima. La cola protesta. Un hombre le grita. Desmemoria no se mueve."],
                      ["desmemoria", "Cerrado. Que la reina me eche si quiere. Este pozo me dio de comer veinte años. Hoy le doy de descansar."],
                      [null, "Esa noche, debajo de la tabla, se oye algo como un suspiro largo."]], end: { xp: 18, flag: "e6_pozoCerrado" } },
      escuchar: { say: [[null, "Te asomas sin respirar. Desde el fondo suben voces, mezcladas: una canción de cuna, una pelea, un nombre, un llanto, una risa. Todo junto."],
                        [null, "Entre todo, una frase clara, repetida: «No era mío. No era mío»."],
                        ["desmemoria", "¿Qué oyó? Su cara está gris. Salga. Lo que la Raíz devuelve ya no es de nadie. Es de todos. Y nadie lo quiere."]], end: { xp: 14, hurt: 0.05, flag: "e6_pozoDevuelve" } },
      otros: { say: [[null, "La cola se parte en dos y va a los otros pozos. Desmemoria se queda solo frente al suyo, mirando el fondo."],
                     ["desmemoria", "Los otros también van a secarse. Es cuestión de tiempo. Y cuando se sequen los tres, la Raíz va a devolver todo de golpe. Ojalá no esté yo."]], end: { xp: 8, flag: "e6_pozosLlenos" } },
    } },

    "e6-reinasola": { kind: "dialogo", need: { era: 6, layer: 3 }, who: { noctambula: "Reina Noctámbula" }, start: "a", nodes: {
      a: { say: [[null, "La reina está sola, sin velo, sentada en el borde del pozo del medio. Es más joven de lo que parece con el velo. Tiene las manos manchadas de tinta de contar."],
                 ["noctambula", "Mañana se decide todo, en el Corazón. Lo sé. La sombra que vendimos sube por la grieta. Mis sombras tienen miedo. Yo también."],
                 ["noctambula", "No quiero perder la tierra. Mi abuela no la perdió. Mi bisabuelo sí, una vez. Toda la vida me contaron eso: la reina que la perdió. No quiero ser esa."]],
           opts: [{ t: "«Usted guarda el secreto de la Raíz. Lo prometí.»", go: "secreto", cNeed: "e6_secretoGuardado" },
                  { t: "«Denuncié el pozo. La Corte tiene hambre por mí.»", go: "denuncia", cNeed: "m6_olvidoDenunciado" },
                  { t: "«Dos pueblos olvidaron su odio en su pozo.»", go: "odio", cNeed: "m6_odioOlvidado" },
                  { t: "«Tapó los pozos por mi palabra.»", go: "comprada", cNeed: "m6_politicaComprada" },
                  { t: "«Una tierra no vale más que la Raíz.»", go: "raiz" },
                  { t: "«Usted no es esa reina. Todavía.»", go: "todavia" }] },
      secreto: { say: [["noctambula", "Lo prometió. Y lo cumplió. Es la primera persona de afuera que guarda algo de la Corte. Me da vergüenza decirlo: me alivia."],
                       ["noctambula", "Mañana, pase lo que pase, sepa que una reina le confió algo. Eso no lo voy a vender."]], back: "a" },
      denuncia: { say: [["noctambula", "Por usted. Sí. La cocina tiene pan para tres días. Los chicos de sombra comen una vez. Lo sé porque cuento."],
                        ["noctambula", "Y aun así, la gente del Prado me saluda distinto. Con miedo, no con asco. No sé qué es mejor. Usted me quitó el negocio y me dio algo que no sé nombrar."]], back: "a" },
      odio: { say: [["noctambula", "El Prado y el Barrio comen juntos. Lo vi. Y lo que olvidaron está en la grieta, subiendo. No me arrepiento. Me asusta."]], back: "a" },
      comprada: { say: [["noctambula", "Su palabra. La Corte en la primera fila. Los pozos con piedra. Mis sombras dicen que vendí la Corte a alguien de afuera. Puede ser."],
                        ["noctambula", "Mañana va a tener que cumplir. Yo cumplí."]], back: "a" },
      raiz: { say: [[null, "Noctámbula se ríe, corto."],
                    ["noctambula", "Eso dicen los que tienen tierra. La Raíz es de todos. La tierra es de alguien. Cuando no tienes tierra, la Raíz no te da de comer."],
                    ["noctambula", "Pero gracias. Nadie me había hablado como si yo pudiera elegir algo más grande que la Corte."]], end: { xp: 16, flag: "e6_reinaDuda" } },
      todavia: { say: [["noctambula", "Todavía. Qué palabra cruel. Y qué amable."],
                       [null, "Se pone el velo despacio. Se levanta. Antes de irse, deja una moneda en el borde del pozo."],
                       ["noctambula", "Para la próxima que venga a olvidar algo. Que sea gratis. Una sola vez. Así empieza a cambiar una reina: con una moneda."]], end: { xp: 18, flag: "e6_reinaMoneda" } },
    } },
  });

  /* ---------- Lago Espejo: el viejo del hielo, las barcas, los ahogados, el espejo, el odio con el Fondo, el hermano de Ondina, las redes y el faro ---------- */
  add("lake", {
    "e6-espuma": { kind: "encuentro", need: { era: 6, layer: 1 }, who: { espuma: "Espuma, carpintero de barcas" }, start: "a", nodes: {
      a: { say: [[null, "En la orilla hay barcas podridas, volteadas, con agujeros. Un viejo flaco de barba blanca martilla una tabla nueva en una de ellas, solo, con mucho cuidado."],
                 ["espuma", "Espuma, carpintero de barcas. El único que queda. Los otros olvidaron el oficio en el pozo, junto con el hielo. Yo no fui. Me acuerdo de cada tabla y de cada ahogado."],
                 ["espuma", "Hago una barca por año. Nadie la usa: los de las Mareas le tienen miedo al agua. Pero la hago. Algún día alguien va a querer volver a salir."]],
           opts: [{ t: "«¿Por qué no fue al pozo?»", go: "porque", once: true },
                  { t: "Ayudarlo a terminar la barca y salir al lago", go: "salir" },
                  { t: "Juntar aprendices de las Mareas para él", go: "aprendices" },
                  { t: "«Venda las barcas a los del Prado, como adorno.»", go: "vender" }] },
      porque: { say: [["espuma", "Porque mi hijo se ahogó cuando se rompió el hielo. Si lo olvido, nadie se acuerda. Su madre fue al pozo. Sus hermanos también."],
                      ["espuma", "Soy el único que sabe que existió. Pesa. Pero si lo suelto, se termina de morir."]], back: "a" },
      salir: { say: [[null, "Terminan la barca en tres días. La empujan al agua una mañana con niebla. Flota. Espuma rema despacio hasta el medio del lago."],
                     [null, "Desde la orilla, los de las Mareas miran. Algunos chicos gritan. Una mujer se tapa los ojos."],
                     ["espuma", "Al medio. Donde se rompió. Hace veinte años que no venía. El agua está quieta. Ahora sé que se puede volver."]], end: { xp: 18, flag: "e6_barcaSale" } },
      aprendices: { say: [[null, "Encuentras tres chicos de las Mareas que quieren aprender. Uno es de los que flotaron diez segundos con Ondina."],
                          [null, "Espuma les enseña a cepillar tablas, a calafatear, a medir con el brazo. Se ríe por primera vez en años cuando uno se martilla el dedo."],
                          ["espuma", "Tres. El oficio no se muere conmigo. No se acuerdan del hielo. Mejor. Van a hacer barcas sin miedo."]], end: { xp: 18, flag: ["e6_barcasAprendices"] } },
      vender: { say: [["espuma", "¿Como adorno? ¿Una barca en el patio de una casa del Prado?"],
                      [null, "Al final las vende. Dos, a las Casas del Farol, que las ponen con flores adentro. Con la plata compra madera buena."],
                      ["espuma", "Las barcas en tierra. Así está el Lago. Por lo menos alguien las mira."]], end: { xp: 8, flag: "e6_barcasAdorno" } },
    } },

    "e6-ahogados": { kind: "encuentro", need: { era: 6, layer: 1 }, who: { ondina: "Ondina, de las Mareas" }, start: "a", nodes: {
      a: { say: [[null, "En una roca de la orilla hay piedras chicas apiladas, muchas, cada una con una marca rayada. Algunas están cubiertas de musgo. Otras, recién puestas."],
                 ["ondina", "Ondina. Son por los ahogados del hielo roto. Cada familia puso una. Después fueron al pozo, y ya nadie sabe qué piedra es de quién. Algunas familias ni saben que pusieron una."],
                 ["ondina", "Los chicos juegan a tirarlas al agua. Nadie los regaña. Nadie sabe que son tumbas."]],
           opts: [{ t: "Ponerle nombre a cada piedra, con la Hondura", go: "nombres" },
                  { t: "Hacer un muro con las piedras, que no se puedan tirar", go: "muro" },
                  { t: "Contarles a los chicos qué son", go: "chicos" },
                  { t: "«Que las tiren. Son piedras.»", go: "tirar" }] },
      nombres: { say: [[null, "Mica sube de las Cuevas con la lista de los ahogados, grabada por un picador que estuvo ahí. Cuarenta y dos nombres."],
                       [null, "Durante una semana, con Ondina, graban un nombre en cada piedra. Sobran tres piedras. Faltan cinco nombres."],
                       ["ondina", "Las que sobran son de alguien que nadie anotó. Les pusimos «sin nombre». Las que faltan, ahora tienen piedra. Las familias vienen a ver. Algunas lloran sin saber por qué."]], end: { xp: 18, flag: "e6_piedrasNombres" } },
      muro: { say: [[null, "Pegan las piedras con barro de la orilla. Queda un muro bajo, torcido, frente al lago. Los chicos se sientan encima a mirar el agua."],
                    ["ondina", "Ya no se pueden tirar. No tienen nombre, pero están juntas. Como en el hielo."]], end: { xp: 14, flag: "e6_piedrasMuro" } },
      chicos: { say: [[null, "Juntas a los chicos en la orilla y les cuentas qué son las piedras. Te escuchan serios. Uno pregunta si su abuelo está ahí. No sabes."],
                      [null, "Esa tarde, los chicos devuelven a la pila las piedras que tiraron antes. Algunas las sacan del agua, mojados hasta la cintura."],
                      ["ondina", "Entraron al agua. Por las piedras. Ninguno sabía nadar bien. Ninguno tuvo miedo."]], end: { xp: 18, flag: "e6_piedrasChicos" } },
      tirar: { say: [["ondina", "Son piedras. Sí. Eso dicen los padres."],
                     [null, "Un chico tira una piedra al agua. Rebota tres veces antes de hundirse. Los otros aplauden."]], end: { xp: 6, flag: "e6_piedrasTiradas" } },
    } },

    "e6-espejo": { kind: "encuentro", need: { era: 6, layer: 2 }, who: { ondina: "Ondina, de las Mareas" }, start: "a", nodes: {
      a: { say: [[null, "En una noche sin viento, el Lago Espejo está tan quieto que refleja el cielo entero. Ondina te lleva a la punta del muelle y te pide que mires el agua."],
                 ["ondina", "Desde que empezaron los pozos, el lago muestra cosas. No el cielo: cosas. Caras, puertas, gente en una fila. Lo que la Raíz traga sale aquí reflejado, de noche, a veces."],
                 [null, "Miras. En el agua hay una fila de gente en la nieve. Una mujer se voltea. Te mira."]],
           opts: [{ t: "«Después del Espejo Roto, el lago no debería mostrar nada.»", go: "roto", cNeed: "m3_espejo" },
                  { t: "Meter la mano en el agua", go: "mano" },
                  { t: "Llamar a la gente de las Mareas a mirar", go: "llamar" },
                  { t: "Tirar una piedra y romper el reflejo", go: "piedra" }] },
      roto: { say: [["ondina", "Eso dicen los viejos. Que hace tres generaciones alguien rompió el espejo del lago, y el agua dejó de mostrar. Y es verdad: de día no muestra nada."],
                    ["ondina", "Pero de noche, desde los pozos, muestra. Como si lo roto se hubiera pegado con lo que la gente olvida. No sé si es el mismo espejo. Es otro, hecho de olvido."]], back: "a" },
      mano: { say: [[null, "Metes la mano en el agua fría. La mujer del reflejo levanta la suya. Las dos se tocan, o eso parece. El agua está tibia donde está ella."],
                    [null, "Después, la imagen se deshace en ondas. La mano te queda tibia toda la noche."],
                    ["ondina", "Ella le dio algo. O le pidió algo. Nunca se sabe con el lago. Mañana a lo mejor sueña con ella."]], end: { xp: 16, flag: "e6_espejoMano" } },
      llamar: { say: [[null, "Ondina llama a los de las Mareas con un silbido. Vienen veinte, en silencio, y se asoman al muelle."],
                      [null, "Un viejo reconoce a alguien en la fila. Dice un nombre. Otro también. Al rato, todos dicen nombres, despacio, bajito."],
                      ["ondina", "Se acordaron. No de lo que olvidaron: de otra cosa, de al lado. Es como pescar. Sale lo que sale."]], end: { xp: 18, flag: "e6_espejoMareas" } },
      piedra: { say: [[null, "Tiras una piedra. El reflejo se rompe en mil pedazos. Cuando el agua se calma, solo muestra el cielo."],
                      ["ondina", "Bien. A veces no hay que mirar. Pero va a volver mañana. El lago no se cansa."]], end: { xp: 8, flag: "e6_espejoRoto" } },
    } },

    "e6-mareasfondo": { kind: "dialogo", need: { era: 6, layer: 2 }, who: { ondina: "Ondina, de las Mareas", sopor: "Sopor, soñadora del Fondo" }, start: "a", nodes: {
      a: { say: [[null, "En la orilla del Lago, una barca del Fondo trae hielo para vender. Los de las Mareas no la dejan atracar. Gritan. Ondina está en el medio, con los brazos abiertos."],
                 ["ondina", "Las Mareas odian al Fondo desde el invierno. Nadie sabe bien por qué: fueron al pozo. Pero el odio quedó. Ya no saben si fue el hielo, el granero o algo más."],
                 ["sopor", "Sopor, del Fondo. Yo sé por qué. Lo sueño. El Fondo cerró el granero y las Mareas se fueron a pescar bajo el hielo para comer. El hielo se rompió. Nadie del Fondo bajó a ayudar."]],
           opts: [{ t: "«Que Sopor cuente lo que sueña. A los dos pueblos.»", go: "contar" },
                  { t: "«Que lo olviden en el pozo, juntos, como el Prado y el Barrio.»", go: "pozo", cNeed: "m6_odioOlvidado" },
                  { t: "«El Fondo debe algo. Que lo pague.»", go: "pagar" },
                  { t: "«Que la barca se vaya. Hoy no.»", go: "irse" }] },
      contar: { say: [[null, "Sopor se sube a la barca y cuenta, en voz alta, lo que sueña cada noche: el hielo roto, la gente en el agua, la puerta del Fondo cerrada."],
                      [null, "Los de las Mareas se callan. Los del Fondo, en la barca, bajan la vista. Un viejo del Fondo dice: «Yo estaba en la puerta. No bajé. Tenía miedo»."],
                      ["ondina", "Ahora sabemos por qué odiamos. Y él lo dijo. No se arregla. Pero ya no es un odio sin dueño. Tiene cara. Y la cara pidió perdón, más o menos."]], end: { xp: 20, flag: "e6_mareasFondoSaben" } },
      pozo: { say: [["ondina", "¿Como el Prado y el Barrio? Ellos comen juntos ahora. No saben por qué se odiaban."],
                    [null, "Las dos gentes van a la Hondonada. Vuelven sin el odio. La barca del Fondo atraca. Les venden hielo a buen precio."],
                    ["sopor", "Yo lo voy a seguir soñando. Alguien tiene que. Esta vez me toca solo a mí."]], end: { xp: 12, flag: "e6_mareasFondoOlvidan" } },
      pagar: { say: [["sopor", "¿Pagar qué? ¿Cuánto vale no haber bajado?"],
                     [null, "Al final el Fondo regala la carga de hielo. Las Mareas la aceptan sin dar las gracias. La barca se va vacía."],
                     ["ondina", "Pagaron. Con hielo, que es lo que tienen. No alcanza. Nunca va a alcanzar. Pero es un comienzo raro."]], end: { xp: 14, flag: "e6_fondoPagaMareas" } },
      irse: { say: [[null, "La barca del Fondo da la vuelta y se va. Los de las Mareas gritan hasta que desaparece en la niebla."],
                    ["ondina", "Hoy no. Mañana tampoco. ¿Cuándo, entonces? Así se pasan los años."]], end: { xp: 6, flag: "e6_mareasFondoOdio" } },
    } },

    "e6-hermano": { kind: "dialogo", need: { era: 6, layer: 3 }, who: { ondina: "Ondina, de las Mareas" }, start: "a", nodes: {
      a: { say: [[null, "Ondina te lleva a la casa de sus padres, una choza de tablas cerca del agua. Los dos viejos están sentados en la puerta, pelando pescado. Saludan con una sonrisa vacía."],
                 ["ondina", "Mis padres. Tenía un hermano. Se ahogó en el hielo. Ellos fueron al pozo y lo olvidaron. Yo no. Yo tenía ocho años y me escondí de la cola."],
                 ["ondina", "Cada vez que los visito, quiero decirles. Que tuvieron otro hijo. Que lo querían. Nunca lo digo. ¿Usted qué haría?"]],
           opts: [{ t: "«Dígales. Es de ellos también.»", go: "decir" },
                  { t: "«No les diga. Ya son felices.»", go: "callar" },
                  { t: "«Llévelos al muro de las piedras. Que vean el nombre.»", go: "piedra", cNeed: "e6_piedrasNombres" }] },
      decir: { say: [[null, "Ondina se sienta con ellos. Les cuenta. Despacio. El nombre, la edad, la risa del hermano, el hielo."],
                     [null, "La madre deja de pelar pescado. El padre la mira como si hablara otro idioma. Después la madre dice: «Por eso siempre pongo un plato de más»."],
                     ["ondina", "No se acordaron. Pero algo se movió. Mi madre pone un plato de más desde hace veinte años y no sabía por qué. Ahora sabe."]], end: { xp: 20, flag: "e6_hermanoDicho" } },
      callar: { say: [[null, "Ondina no dice nada. Pela pescado con ellos. Se ríen de una tontería del vecino."],
                      ["ondina", "Felices. Sí. Y yo con él adentro, solo yo. Así va a ser hasta que me muera. Después, nadie."]], end: { xp: 10, flag: "e6_hermanoCallado" } },
      piedra: { say: [[null, "Llevan a los viejos al muro. Ondina les señala una piedra con un nombre grabado. Los padres la leen."],
                      [null, "El padre toca la piedra con la punta de los dedos. «Qué nombre lindo». La madre dice que le suena. Que le suena mucho."],
                      ["ondina", "Le suena. Eso alcanza. Desde hoy vienen todas las tardes a sentarse en el muro. No saben por qué. Yo sé."]], end: { xp: 20, flag: "e6_hermanoPiedra" } },
    } },

    "e6-redes": { kind: "encuentro", need: { era: 6, layer: 3 }, who: { espuma: "Espuma, carpintero de barcas" }, start: "a", nodes: {
      a: { say: [[null, "Esta mañana las redes que Espuma tiró desde su barca salieron llenas. No de peces: de cosas. Una cinta de pelo, un zapato chico, una carta mojada, un tambor roto."],
                 ["espuma", "La Raíz devuelve. Lo que se olvidó, sale. Por el agua. Desde hace una semana. Cada mañana más."],
                 ["espuma", "Nadie sabe de quién son. La gente viene a mirar y se va con miedo. Alguno se lleva algo, sin saber por qué."]],
           opts: [{ t: "Poner las cosas en la orilla para que cada uno elija", go: "orilla" },
                  { t: "Llevárselas a la Hondura para guardar", go: "hondura" },
                  { t: "Devolverlas al agua", go: "agua" }] },
      orilla: { say: [[null, "Ponen todo sobre una manta larga en la orilla. Viene gente de las Mareas, del Prado, de la Hondonada. Miran. Tocan. Algunos se llevan algo."],
                      [null, "Una mujer agarra la carta mojada. La lee. Se sienta en la arena. No se mueve en toda la tarde."],
                      ["espuma", "Era suya. No se acordaba de que la había escrito. Ahora se acuerda de que no la mandó."]], end: { xp: 18, flag: "e6_redesOrilla" } },
      hondura: { say: [[null, "Llevas las cosas a las Cuevas en un saco. Mica las pone en una galería, en estantes de piedra, con una tablilla cada una: «Salió del lago. De nadie»."],
                       ["espuma", "Un museo de lo olvidado. La Hondura junta todo. Algún día va a necesitar el Claro entero para guardarlo."]], end: { xp: 14, flag: "e6_redesCuevas" } },
      agua: { say: [[null, "Espuma tira todo al lago desde la barca. Las cosas se hunden despacio."],
                    [null, "A la mañana siguiente, las redes salen con las mismas cosas. Y más."],
                    ["espuma", "No quiere. La Raíz no quiere que se lo devuelvan. Está llena."]], end: { xp: 8, flag: "e6_redesDevueltas" } },
    } },

    "e6-faro": { kind: "encuentro", need: { era: 6, layer: 3 }, who: { calima: "Calima, guarda del faro" }, start: "a", nodes: {
      a: { say: [[null, "En la punta de las rocas hay un faro chico, de piedra, con una luz de aceite arriba. Una mujer de manos ásperas sube la escalera con una lata de aceite."],
                 ["calima", "Calima, guarda del faro. Lo prendo cada noche. Nadie sale al lago, ninguna barca lo necesita. Mi abuela lo prendía para los pescadores. Yo lo prendo porque mi abuela lo prendía."],
                 ["calima", "La reina de la Corte me mandó una oferta: comprar el faro para poner un pozo arriba. Dice que la luz no sirve. Que el olvido sí."]],
           opts: [{ t: "«Espuma salió al lago en barca. El faro sirve otra vez.»", go: "barca", cNeed: "e6_barcaSale" },
                  { t: "«No lo venda. Los chicos están aprendiendo a nadar.»", go: "chicos", cNeed: "e6_ninosNadan" },
                  { t: "«Véndalo. El lago está vacío.»", go: "vender" },
                  { t: "Subir con ella a prender el faro", go: "subir" }] },
      barca: { say: [["calima", "¿Espuma? ¿El viejo loco de las barcas? ¿Salió de verdad?"],
                     [null, "Esa noche, desde el faro, ven una lucecita en el medio del lago: la barca de Espuma, con un farol en la proa. Calima la saluda moviendo la luz del faro, tres veces."],
                     ["calima", "Me contestó. Con el farol. Mi abuela hacía eso. Ya no vendo nada."]], end: { xp: 18, flag: "e6_faroBarca" } },
      chicos: { say: [["calima", "¿Aprenden? ¿A nadar? ¿Ondina, con los chicos en la orilla?"],
                      ["calima", "Si aprenden a nadar, van a querer barcas. Si tienen barcas, van a necesitar el faro. Bueno. Le digo a la reina que no. Que vuelva en diez años."]], end: { xp: 16, flag: "e6_faroGuardado" } },
      vender: { say: [[null, "Calima vende el faro. La Corte sube la sombra en baldes. Al mes, arriba del faro hay un pozo chico, y una cola en la escalera."],
                      ["calima", "La luz era de mi abuela. La plata es mía. Ya no sé qué es peor."]], end: { xp: 8, flag: "e6_faroVendido" } },
      subir: { say: [[null, "Subes con Calima la escalera de caracol. Arriba hace viento. Ella prende la mecha con cuidado. La luz se mueve sobre el agua negra."],
                     ["calima", "Nadie la mira. Pero si alguna vez alguien está perdido en el lago, va a estar. Eso es un faro: algo que se prende por si acaso."],
                     [null, "Te quedas toda la noche. A la madrugada, desde la orilla, un chico de las Mareas saluda al faro con la mano."]], end: { xp: 16, flag: "e6_faroPrendido" } },
    } },

    "e6-niebla": { kind: "encuentro", need: { era: 6, layer: 2 }, who: { ondina: "Ondina, de las Mareas" }, start: "a", nodes: {
      a: { say: [[null, "Una niebla espesa cubre el Lago desde hace tres días. Huele a tierra mojada, como la sombra de los pozos. Dentro de la niebla se oyen voces."],
                 ["ondina", "No es niebla. Es sombra que sube del agua. La Raíz está tan llena que se le sale por el lago. Los chicos tienen miedo de ir a la orilla."],
                 ["ondina", "Algunos de las Mareas entran a la niebla a propósito. Dicen que adentro se olvida gratis. Salen sin saber quiénes son por un rato."]],
           opts: [{ t: "Entrar en la niebla y sacar a los que están adentro", go: "entrar" },
                  { t: "Cantar la nana en la orilla, fuerte", go: "cantar" },
                  { t: "«Que nadie entre. Pongan una soga en la orilla.»", go: "soga" }] },
      entrar: { say: [[null, "Entras con una soga atada a la cintura. Adentro no se ve nada. Las voces te dicen nombres que no son tuyos. Por un momento no sabes por qué entraste."],
                      [null, "Te tropiezas con alguien: un hombre sentado en el barro, mirando nada. Lo sacas de la mano. Afuera, parpadea. Dice su nombre como si lo leyera por primera vez."],
                      ["ondina", "Volvió. Usted también. Tiene la cara gris. Siéntese. Le traigo agua. No, agua no: sopa."]], end: { xp: 18, hurt: 0.05, flag: "e6_nieblaRescate" } },
      cantar: { say: [[null, "Te paras en la orilla y cantas la nana, fuerte. Ondina se suma. Después, los chicos que la aprendieron en el Prado."],
                      [null, "La niebla se mueve. Se abre un poco, como cortina. Del otro lado salen tres personas caminando, despacio, siguiendo la canción."],
                      ["ondina", "La siguieron. La nana es lo único que la Raíz todavía reconoce. Todo lo demás lo mezcla. Esto no."]], end: { xp: 20, flag: "e6_nieblaNana" } },
      soga: { say: [[null, "Ponen una soga de poste en poste a lo largo de la orilla. Nadie cruza. La niebla se queda en el agua, quieta."],
                    ["ondina", "Así no entra nadie. Ni sale. Los que están adentro, ahí se quedan. No sé si los salvamos o los dejamos."]], end: { xp: 8, flag: "e6_nieblaSoga" } },
    } },
  });

  /* ---------- Cuevas del Eco: el que raspa, los picadores, la pared que repite, los rollos de la Corte, la hija de Mica, los cuarenta, el precio de leer y la pared más honda ---------- */
  add("caves", {
    "e6-raspa": { kind: "encuentro", need: { era: 6, layer: 1 }, who: { raspa: "Raspa, el que borra de noche", mica: "Mica, de la Hondura" }, start: "a", nodes: {
      a: { say: [[null, "De noche, en una galería de las Cuevas, se oye un ruido de piedra contra piedra. Con una lámpara encuentras a un hombre raspando una pared con un cuchillo de hierro."],
                 ["raspa", "Raspa. Así me dicen. Me pagan para borrar. Las Casas, el Gremio, alguno que se arrepintió. Cada uno quiere borrar una línea, la suya. Yo borro."],
                 ["mica", "Hace un mes que faltan líneas. Pensé que la piedra se gastaba. Era él."]],
           opts: [{ t: "«¿Quién le pagó por esta línea?»", go: "quien", once: true },
                  { t: "Llevarlo ante la Hondura", go: "hondura" },
                  { t: "«Que vuelva a grabar lo que borró.»", go: "volver" },
                  { t: "«Déjenlo. Cada uno tiene derecho a una línea.»", go: "derecho" }] },
      quien: { say: [["raspa", "Un hombre de bastón con punta de plata. No dijo su nombre. Quería borrar una lista de leña."],
                     ["mica", "Lumbre. De las Casas. La lista de leña está en tres paredes. Le borró una. Le quedan dos."]], back: "a" },
      hondura: { say: [[null, "La Hondura lo juzga en la galería grande. Los picadores escuchan. Raspa no niega nada."],
                       [null, "Lo condenan a volver a grabar, de memoria o copiando de otras paredes, todo lo que borró. Le dan un punzón en lugar del cuchillo."],
                       ["mica", "Un borrador convertido en grabador. Va a tardar años. Al final va a saber más del Claro que nadie."]], end: { xp: 18, flag: "e6_raspaGraba" } },
      volver: { say: [["raspa", "¿De memoria? No me acuerdo. Borro sin leer. Es la regla."],
                      [null, "Mica le pone al lado una copia de la otra pared. Raspa graba línea por línea, toda la noche, con la lengua afuera."],
                      ["raspa", "Ahora sé lo que borré. Es feo. La próxima vez que me paguen, voy a leer antes."]], end: { xp: 16, flag: "e6_raspaLee" } },
      derecho: { say: [["mica", "¿Una línea? ¿Y si todos quieren una? ¿Cuántas quedan?"],
                       [null, "Raspa sigue raspando, más tranquilo. Mica se va sin decir nada. Esa noche graba la línea borrada en otra pared, más alta, donde no llega el cuchillo."]], end: { xp: 8, flag: "e6_raspaSigue" } },
    } },

    "e6-picadores": { kind: "encuentro", need: { era: 6, layer: 1 }, who: { mica: "Mica, de la Hondura" }, start: "a", nodes: {
      a: { say: [[null, "En la galería de trabajo, los picadores de la Hondura discuten a gritos. La mitad tiene punzones de grabar. La otra mitad, picos de mina."],
                 ["mica", "Los de la mina dicen que la Hondura se olvidó de sacar piedra. Que graba y graba y no vende nada. Que tenemos hambre por acordarnos de los demás."],
                 ["mica", "Y tienen razón. No vendemos memoria. La damos. Nadie paga por acordarse. Todos pagan por olvidar."]],
           opts: [{ t: "«Que la Hondura cobre por leer las paredes.»", go: "cobrar" },
                  { t: "«Medio día cada cosa. Mina en la mañana, pared en la tarde.»", go: "mitad" },
                  { t: "Pedirles a los otros pueblos que paguen la memoria con comida", go: "pueblos" }] },
      cobrar: { say: [[null, "Ponen una mesa a la entrada de las galerías escritas. Una moneda por leer una pared. Al principio viene poca gente. Después, menos."],
                      ["mica", "Nadie paga por saber lo que hizo. Salvo los que quieren borrarlo. Esos pagan bien. Me da asco."],
                      [null, "A la semana sacan la mesa. Vuelven a picar mina por la mañana."]], end: { xp: 10, flag: "e6_paredCobrada" } },
      mitad: { say: [[null, "Los picadores se reparten el día. En la mañana, mina. En la tarde, paredes. Comen, graban, duermen poco."],
                     ["mica", "Es agotador. Pero nadie quedó afuera. Los de la mina aprenden a grabar. Los de la pared aprenden a sacar piedra. Así la Hondura no se parte."]], end: { xp: 16, flag: "e6_hondaMitad" } },
      pueblos: { say: [[null, "Vas al Prado, al Cráter, al Bosque. Les cuentas que la Hondura guarda lo que ellos olvidan. Que tiene hambre."],
                       [null, "El Barrio manda pan de la mesa larga. El Bosque, centeno. El Cráter, punzones nuevos, gratis, de la maestra Crisol."],
                       ["mica", "Primera vez que alguien le paga a la Hondura por acordarse. No es mucho. Pero es un pago. Ahora la memoria vale algo."]], end: { xp: 18, flag: "e6_memoriaPagada" } },
    } },

    "e6-paredrepite": { kind: "dialogo", need: { era: 6, layer: 2 }, who: { pared: "La pared" }, start: "a", nodes: {
      a: { say: [[null, "En lo más hondo, la pared lisa que hablaba cuando alguien le apoyaba la frente ahora habla sola. Sin que nadie la toque. Muchas voces a la vez, rápido, como alguien con fiebre."],
                 ["pared", "Fila. Puerta. Llave. Hambre. Nombre, nombre, nombre. No era mío. No era mío. Tanto. Tanto."],
                 ["pared", "Abajo lleno. Arriba olvidan. Abajo guarda. ¿Quién guarda a abajo?"]],
           opts: [{ t: "«¿Quién le manda todo esto?»", go: "quien", once: true },
                  { t: "Apoyar la frente y repetir lo que dice, para que alguien lo grabe", go: "grabar" },
                  { t: "Cantarle la nana", go: "nana" },
                  { t: "«Nadie la guarda. Lo siento.»", go: "nadie" }] },
      quien: { say: [["pared", "Pozos. Arriba. Mil bocas. Tragan, tragan. Mandan aquí. Raíz traga. Raíz no olvida. Raíz no puede olvidar."],
                     ["pared", "Antes dos cantaban y Raíz dormía. Ahora mil olvidan y Raíz no duerme."]], back: "a" },
      grabar: { say: [[null, "Apoyas la frente. Repites en voz alta lo que oyes. Mica graba detrás de ti, rápido. Son nombres, cosas, pedazos. Llenan una galería entera en una noche."],
                      [null, "Al amanecer, la pared se calla. Un momento. Después, más bajito, dice: «Gracias. Menos»."],
                      [null, "Mica se sienta en el suelo, con la mano dormida. «Le sacamos un poco. Un poco»."]], end: { xp: 20, flag: "e6_paredAliviada" } },
      nana: { say: [[null, "Cantas la nana con la frente en la piedra. La pared se calla mientras cantas. Cuando terminas, vuelve a hablar, pero más lento."],
                    ["pared", "Esa. Esa es mía. Esa no la olvidaron arriba. Esa la cantan. Otra vez."],
                    [null, "La cantas otra vez. Y otra. Hasta que la pared se queda callada, como quien se duerme."]], end: { xp: 18, flag: "e6_paredDuerme" } },
      nadie: { say: [["pared", "Nadie. Sí. Nadie. Siempre nadie."],
                     [null, "La pared vuelve a hablar rápido. Más rápido que antes. Te vas con el ruido en la cabeza."]], end: { xp: 8, flag: "e6_paredSola" } },
    } },

    "e6-rollos": { kind: "encuentro", need: { era: 6, layer: 2, flag: "e6_archivoCopiado" }, who: { mica: "Mica, de la Hondura", legajo: "Legajo, archivero del Velo", noctambula: "Reina Noctámbula" }, start: "a", nodes: {
      a: { say: [[null, "En la galería donde la Hondura copió los rollos de Legajo hay cuatro sombras con velo. Tienen martillos. Detrás de ellas, Legajo, con las manos atadas."],
                 ["mica", "La Corte se enteró. Vinieron a romper la pared. Trajeron a Legajo para que vea."],
                 ["legajo", "No dije nada. Lo juro. Alguien me siguió una noche con el saco. Perdón, Mica. Perdón."]],
           opts: [{ t: "Ponerte delante de la pared", go: "delante" },
                  { t: "«Que lo decida la reina en persona.»", go: "reina" },
                  { t: "«Rompan una línea. La que ustedes elijan. Las demás se quedan.»", go: "una" }] },
      delante: { say: [[null, "Te paras delante de la pared, con los brazos abiertos. Mica se pone a tu lado. Después, uno por uno, los picadores de la Hondura."],
                       [null, "Las sombras miran. Treinta personas delante de una pared. Bajan los martillos. Se van. Dejan a Legajo atado."],
                       ["legajo", "Se fueron. La pared se queda. Yo... yo ya no puedo volver a la Corte. ¿Hay lugar aquí para un archivero?"]], end: { xp: 20, flag: "e6_legajoHondura" } },
      reina: { say: [[null, "Las sombras dudan. Mandan a una a buscar a la reina. Vuelve de noche con Noctámbula."],
                     [null, "La reina lee la pared un rato largo. Lee la lista de mantas que no se dieron. Lee su propia orden."],
                     ["noctambula", "Déjenla. Desátenlo. Que la Hondura la guarde. Prefiero que esté aquí, lejos, a que esté en mi casa. Legajo vuelve conmigo. Y no vuelve a copiar nada sin decirme."]], end: { xp: 16, flag: "e6_paredReina" } },
      una: { say: [[null, "Las sombras eligen. Rompen la línea de la orden de la reina, la que decía «no den mantas». Un pedazo de piedra cae al suelo."],
                   ["mica", "Una. La de arriba. Lo demás se queda. Los nombres de los que no recibieron mantas siguen ahí. Solo falta quién mandó."],
                   ["legajo", "Yo me acuerdo de quién mandó. Pero no lo voy a decir. Ya rompieron lo que querían."]], end: { xp: 12, flag: "e6_paredRota" } },
    } },

    "e6-hijamica": { kind: "encuentro", need: { era: 6, layer: 2 }, who: { mica: "Mica, de la Hondura" }, start: "a", nodes: {
      a: { say: [[null, "Mica está en la entrada de las Cuevas, con los brazos cruzados, delante de una muchacha de dieciséis años con una moneda en la mano. Las dos tienen la misma cara, enojada."],
                 ["mica", "Mi hija. Quiere ir al pozo. Una de la Hondura, mi hija, quiere ir al pozo."],
                 [null, "La muchacha dice que le pegaron en el Prado por ser de la Hondura. Que le dijeron «la de las paredes», «la que no deja olvidar». Que quiere olvidarlo. Que no quiere ser la de las paredes."]],
           opts: [{ t: "«¿Qué es lo que quiere olvidar, exactamente?»", go: "que", once: true },
                  { t: "«Déjela ir. Es su memoria.»", go: "dejar" },
                  { t: "Ir con la muchacha al Prado a hablar con los que le pegaron", go: "prado" },
                  { t: "«Que lo grabe en una pared, y que sea la última vez que lo lea.»", go: "grabar" }] },
      que: { say: [[null, "La muchacha dice que no el golpe: la palabra. «La de las paredes». Que se le quedó pegada."],
                   ["mica", "La palabra. Eso somos. Eso soy yo. Si la olvida, me olvida un poco a mí."]], back: "a" },
      dejar: { say: [["mica", "Su memoria. Sí. Tiene razón. No la tengo."],
                     [null, "La muchacha se va hacia la Hondonada. Vuelve a los dos días. No recuerda el golpe ni la palabra. Mira las paredes de las Cuevas como si fueran de otro pueblo."],
                     ["mica", "Volvió. Distinta. No sé si es feliz. Yo no. Pero era suya."]], end: { xp: 12, flag: "e6_hijaOlvida" } },
      prado: { say: [[null, "Vas con la muchacha al Prado. Encuentras a los chicos. Son tres, de las Casas. Uno es de la clase de Mimbre, la que bajó a leer las paredes."],
                     [null, "El chico se pone rojo. Dice que no quería. Que los otros le dijeron que la Hondura les guarda los pecados a todos. Que les daba miedo."],
                     [null, "La muchacha lo escucha. Después le dice: «Tu bisabuela está en la pared. Yo la grabé. Es la que guardó leña». El chico se va callado. Ella vuelve a las Cuevas sin moneda."]], end: { xp: 18, flag: "e6_hijaFirme" } },
      grabar: { say: [[null, "La muchacha graba en una pared chica, en una galería vacía: el golpe, la palabra, los nombres de los tres chicos."],
                      [null, "Lo lee una vez. Después tapa la pared con barro, ella misma."],
                      ["mica", "Ahí está. Guardado y tapado. Ni olvidado ni a la vista. No sabía que se podía. Mi hija lo inventó."]], end: { xp: 16, flag: "e6_hijaTapa" } },
    } },

    "e6-cuarentahoy": { kind: "encuentro", need: { era: 6, layer: 3 }, who: { mica: "Mica, de la Hondura" }, start: "a", nodes: {
      a: { say: [[null, "En la galería de los Cuarenta, la de los mineros de las Forjas Hondas, hay una cola. No es cola para olvidar. Es gente que vino a tocar la pared de los nombres."],
                 ["mica", "Los Cuarenta. Mineros de hace dos generaciones. Las familias los olvidaron en el pozo, pero los hijos de los hijos vienen igual. No saben por qué. Dicen que algo los trae."],
                 ["mica", "La Corte quiere comprar esta galería. Dice que es la más pedida. Que pondría un pozo aquí, para que la gente olvide a los Cuarenta de una vez, ya que viene a sufrir."]],
           opts: [{ t: "«Los Cuarenta quedaron tapiados. Los nombres son lo único que hay.»", go: "tapiada", cNeed: "e5_cuarentaTapiada" },
                  { t: "«Están dormidos y tibios. No se les pone un pozo encima.»", go: "tibia", cNeed: "m5_cuarentaTibia" },
                  { t: "«Ni pozo ni venta. Que la gente siga viniendo.»", go: "no" },
                  { t: "«Véndala. La Hondura necesita comer.»", go: "vender" }] },
      tapiada: { say: [["mica", "Tapiados. Detrás de esa pared. Mi madre decía que a veces se oían golpes. Yo de chica los oía. Ahora no."],
                       ["mica", "Si ponen un pozo aquí, los nombres se olvidan y la pared queda sola. Sin nadie que sepa qué hay detrás. No."]], back: "a" },
      tibia: { say: [["mica", "Tibios. La galería no se enfrió nunca. Los que tocan la pared dicen que está caliente. Como una espalda."],
                     ["mica", "No se pone un pozo sobre alguien que duerme. Ni la Corte haría eso, si supiera."]], back: "a" },
      no: { say: [[null, "Mica le manda la respuesta a la reina en una piedra tallada: «No»."],
                  [null, "La cola sigue viniendo. Una vieja deja una flor seca al pie de la pared. Un chico toca un nombre y dice que es el suyo, el de su bisabuelo."],
                  ["mica", "Vienen a sufrir. La reina tiene razón. Pero vienen. Eso es más de lo que hace el pozo."]], end: { xp: 18, flag: "e6_cuarentaQuedan" } },
      vender: { say: [["mica", "Comer. Sí. La Hondura tiene hambre."],
                      [null, "Venden la galería. La Corte pone un pozo chico al pie de la pared. La cola cambia: ahora viene gente a olvidar a los Cuarenta."],
                      [null, "Al mes, los nombres de la pared están cubiertos de sombra. Ya no se leen. Nadie viene a tocarlos."]], end: { xp: 8, flag: "e6_cuarentaVendida" } },
    } },

    "e6-honda": { kind: "dialogo", need: { era: 6, layer: 3 }, who: { mica: "Mica, de la Hondura", pared: "La pared" }, start: "a", nodes: {
      a: { say: [[null, "Mica te lleva más abajo que nunca, por un túnel que cavó su madre y que nadie usa. Al final hay una pared negra, sin letras. Es tibia. Late."],
                 ["mica", "Esta pared no la grabó nadie. Ya estaba. Dice cosas cuando se la toca. No lo que olvidan arriba: otra cosa. Lo que la Raíz recuerda de sí misma."],
                 ["pared", "Primero. Antes de todos. Una cantó. Dos cantaron. Pacto. No canto: memoria. Recordar a quien cuida. Recordar a quien cuida."]],
           opts: [{ t: "«¿Quién es quien cuida?»", go: "quien", once: true },
                  { t: "Grabar lo que dice, al lado, para que quede", go: "grabar" },
                  { t: "«Esto no lo puede saber nadie de arriba. Tapémosla.»", go: "tapar" },
                  { t: "Apoyar la frente y quedarte", go: "quedar" }] },
      quien: { say: [["pared", "Tú. Antes. Otros antes. Siempre uno. Cuida a criatura, criatura cuida a Raíz. Raíz recuerda. Si nadie recuerda a quien cuida, Raíz olvida pacto."],
                     ["mica", "Habla del Cuidador. De usted. O de los de antes. No sé. Nunca la oí decir eso."]], back: "a" },
      grabar: { say: [[null, "Mica graba al lado de la pared negra, en la piedra común, lo que dice: «El pacto no es un canto. Es recordar a quien cuida»."],
                      ["mica", "Ahora está escrito. No sé qué significa. Pero alguien, alguna vez, lo va a necesitar. Tal vez el noveno verso diga lo mismo."]], end: { xp: 20, flag: "e6_pactoGrabado" } },
      tapar: { say: [[null, "Tapan el túnel con piedras, Mica y tú, toda la noche. Al final, del otro lado, la pared sigue latiendo. Se siente en el suelo."],
                     ["mica", "Tapado. Que nadie lo venda. Que nadie lo olvide en un pozo. Lo sabemos usted y yo. Eso pesa. Ya sé por qué mi madre cavó y no le contó a nadie."]], end: { xp: 14, flag: "e6_pactoTapado" } },
      quedar: { say: [[null, "Apoyas la frente en la piedra tibia. Pasa mucho tiempo. La pared no dice nada más. Solo late, despacio, con tu respiración."],
                      [null, "Cuando te separas, tienes una sensación rara: que alguien, muy abajo, sabe cómo te llamas."],
                      ["mica", "Le pasó algo. Lo veo. No me cuente. O sí. Algún día."]], end: { xp: 18, heal: 0.15, flag: "e6_raizConoce" } },
    } },

    "e6-ecosnuevos": { kind: "encuentro", need: { era: 6, layer: 1 }, who: { mica: "Mica, de la Hondura" }, start: "a", nodes: {
      a: { say: [[null, "En una galería nueva, alguien deja cosas al pie de la pared: una cuchara, un zapato de niño, una carta doblada. Cada una con un papelito: «Para que la piedra se acuerde por mí»."],
                 ["mica", "Empezó hace un mes. La gente que no quiere ir al pozo, pero no aguanta acordarse, viene aquí. Deja la cosa. Se va más liviana. La piedra la guarda."],
                 ["mica", "No sé si está bien. Es como un pozo al revés. No olvidan: dejan que otro se acuerde."]],
           opts: [{ t: "«Es mejor que el pozo. Que sigan viniendo.»", go: "seguir" },
                  { t: "Ayudar a Mica a anotar de quién es cada cosa", go: "anotar" },
                  { t: "«La Hondura no es un depósito. Que se las lleven.»", go: "llevar" }] },
      seguir: { say: [[null, "La galería se llena. Cucharas, zapatos, cartas, un sombrero, un tambor chico, un muñeco de trapo."],
                      ["mica", "La Hondura se va a quedar sin espacio. Pero la gente duerme. Y nadie se olvida de nada: solo lo dejó en otro lado. Un lugar para cargar lo que pesa."]], end: { xp: 16, flag: "e6_galeriaCosas" } },
      anotar: { say: [[null, "Durante una semana, al lado de cada cosa, grabas con Mica una línea: quién la trajo, cuándo, por qué, si lo dijo."],
                      ["mica", "Ahora cada cosa tiene historia. Si alguien vuelve a buscarla, la encuentra. Algunos van a volver. Lo sé."]], end: { xp: 18, flag: "e6_galeriaAnotada" } },
      llevar: { say: [["mica", "Tiene razón. Aquí se graba. No se guarda lo de otros."],
                      [null, "Al otro día, Mica pone un cartel. La gente se lleva sus cosas. Algunos, en vez de irse a su casa, se van hacia la Hondonada."]], end: { xp: 8, flag: "e6_galeriaVacia" } },
    } },
  });

})(window.EVEVENTS);
